window.WPU_COURSE_CATALOG = {"source":"2026-2027AcademicCatalog9.2.26.pdf","method":"Extracted from the catalog Course Descriptions section","courses":{"APCS 101":{"code":"APCS 101","title":"Introduction to Computing Professions","credits":"1","description":"Students will be introduced to various concepts regarding coursework, careers, industries, opportunities, and expectations of Applied Computing professionals. Students will be guided through creating and maintaining an online professional presence and portfolio. Offered fall semester during 2nd 8-week module.","offering":"Offered fall semester during 2nd 8-week module.","sourcePage":117},"APCS 109":{"code":"APCS 109","title":"Intro to Technology Topics: Hardware & Devices","credits":"1","description":"Students will be introduced to various topics regarding computing hardware and associated devices. Topics may include hardware usage, relevancy, and troubleshooting. Students will be expected to understand and explain the implementation of various hardware solutions and issues that may be commonly encountered in the workplace. Prerequisite: LDRS 105","offering":"","sourcePage":117},"APCS 110":{"code":"APCS 110","title":"Intro to Technology Topics: Platforms & Operating Systems","credits":"1","description":"This course will prepare students to successfully navigate and utilize multiple computing platforms in a working environment. Students will be expected to complete tasks and communicate issues utilizing various platforms successfully. Topics may include managing tasks such as navigating the interface with a mouse or touchscreen, connecting to the web, troubleshooting, managing devices, and files with both desktop and mobile platforms across multiple operating systems. Prerequisite: LDRS 105","offering":"","sourcePage":117},"APCS 111":{"code":"APCS 111","title":"Introduction to Technology Topics","credits":"1","description":"Each offering of this course will introduce a recent trend in technology in an 8-week project-driven format. Students will view and experience (through mini-lecture and projects) relevant technology topics to better understand technology and use of technology. Topics could include AI/ML, hacking, cryptocurrency (bitcoin), drones, robotics, 3D printing, augmented reality, virtual reality, quantum computing, IoT, mobile devices, and other topics. May be repeated once for credit. Offered fall and spring semesters during 2nd 8-week module.","offering":"Offered fall and spring semesters during 2nd 8-week module.","sourcePage":117},"APCS 112":{"code":"APCS 112","title":"Computer Applications for Communications","credits":"3","description":"Advanced survey of communication application software, which includes advanced word processing, desktop publishing and E-Commerce. Topics with word-processing include mail-merge and web page development. Topics with desktop publishing include multi-page layouts, typesetting, working with tables, grouped items and layers for producing brochures or newsletters. Topics with E-Commerce include business on the Internet, business services online, Internet marketing, digital advertising and web site development. Lab experience with microcomputer software. Lab fee required. Typically offered fall semester. Prerequisite: LDRS 105","offering":"Typically offered fall semester.","sourcePage":117},"APCS 114":{"code":"APCS 114","title":"Computer Applications for Business","credits":"3","description":"Advanced survey of business application software, which includes spreadsheets, databases, presentation software, and file manipulation on networks. Topics with spreadsheets include design and development, advanced formulas and functions, charting and formatting, and the use of business analysis tools. Topics with databases include design and development of tables, queries, forms and reports for business information purposes. Also included is business communication and presentation software with an emphasis on integrating them with the spreadsheets and databases. Lab experience with microcomputer software. Lab fee required. Offered every fall and spring semester. Prerequisite: LDRS 105","offering":"Offered every fall and spring semester.","sourcePage":118},"APCS 116":{"code":"APCS 116","title":"Geographic Information Systems (GIS)","credits":"3","description":"Introduction to terminology, concepts, applications, data acquisition, trends, and careers in Geographic Information Systems (GIS), computer-based mapping software. Includes an overview of related technologies, such as Global Positioning Systems (GPS) and Remote Sensing (RS), as well as hands-on use of GPS and GIS to explore the creation, management, analysis, and mapping of geospatial data across various disciplines, including environment, conservation, business, agriculture, government, transportation, public safety, recreation, Science and technology. Includes a community project using geospatial applications. Offered fall semester.","offering":"Offered fall semester.","sourcePage":118},"APCS 201":{"code":"APCS 201","title":"Programming Fundamentals","credits":"2","description":"Concepts of structured programming including control structure design – sequence, selection, iteration and method call; concepts of data abstraction including primitive data types, strings, arrays, library objects and files. Laboratory experience emphasizing application development. Includes a brief introduction to using artificial intelligence in the software development process. Offered spring semester during 1st 8-week module. Prerequisite: LDRS 105","offering":"Offered spring semester during 1st 8-week module.","sourcePage":118},"APCS 206":{"code":"APCS 206","title":"Object Oriented Programming","credits":"2","description":"Concepts of object-oriented programming including the use of objects and the design of classes including inheritance. Also covers AI API usage and algorithm development including searching, sorting and recursion. Laboratory experience emphasizing application development including introduction of AI assisted development tooling. Offered spring semester during 2nd 8-week module. Prerequisite: C- or higher in APCS 201","offering":"Offered spring semester during 2nd 8-week module.","sourcePage":118},"APCS 207":{"code":"APCS 207","title":"Command Line Interface & Scripting Language","credits":"3","description":"Students will explore and be introduced to the various command line interfaces, operating system navigation, command line editing including PowerShell, for network automation scripting using AI for cybersecurity, and various other terminal technologies. Offered spring semester. Lab fee required. Prerequisite: APCS 201 or consent of instructor.","offering":"Offered spring semester.","sourcePage":118},"APCS 215":{"code":"APCS 215","title":"Graphical User Interface Programming","credits":"3","description":"Introduces the principles of event-driven programming and the development of applications with graphical user interfaces. Students learn to design and implement interactive applications using concepts such as event handling, user interface components, layout design, data input/output, and integration with external resources such as General Artificial Intelligence APIs. The course emphasizes the use of a modern UI framework to build responsive, user-friendly applications. Offered fall semester of even numbered years. Lab fee required. Prerequisite: APCS 206 or consent of instructor","offering":"Offered fall semester of even numbered years.","sourcePage":118},"APCS 216":{"code":"APCS 216","title":"GIS for Decision Makers","credits":"3","description":"Examine the use of GIS on an Intermediate level to see how decision-makers use Geographic Information Systems (GIS) to analyze data and support spatial decisions. Scenarios in a variety of real-world situations, such as Hazardous Emergency Decisions, Demographic Decisions, Law Enforcement, Disaster Damage, Urban Planning, and other real- time situations will provide opportunities for questions and analysis using GIS platforms, including Online, Desktop, and Mobile. Group or individual projects will incorporate asking a question, acquiring data to help answer the question, analyzing the data, and creating appropriate deliverables for the target audience.","offering":"","sourcePage":119},"APCS 220":{"code":"APCS 220","title":"Computer Organization & Digital Circuits","credits":"3","description":"Introduction to the fundamental principles of digital logic analysis and design, computer organization, and digital communication. Includes logic elements, asynchronous logic, microprocessors, computer architecture, assembly language programming, and operating systems. Lab fee required. Offered spring semester. Prerequisites: MATH 211 and APCS 201 or consent of instructor","offering":"Offered spring semester.","sourcePage":119},"APCS 225":{"code":"APCS 225","title":"File Processing (COBOL)","credits":"3","description":"Concepts of establishing, maintaining, updating, and processing computer data files and databases for generating management information reports. Includes program planning and design, control-break processing, on-line processing, sequential and indexed files, database access, and maintenance programming. Emphasis will be placed on using COBOL in a multi-user environment. Lab fee required. Offered on demand. Prerequisite: APCS 201","offering":"Offered on demand.","sourcePage":119},"APCS 236":{"code":"APCS 236","title":"Virtual Reality & Interactive Graphics","credits":"3","description":"Students will be exposed to the design of interactive 3D VR environments using industry standard programming languages and gaming engines in a hands-on lab atmosphere. Concepts of object-oriented programming languages, real-time rendering, graphic user interfaces, user interactivity within virtual environments, real-time programming techniques, as well as the creation of 3D assets and texturing from real-world environments will be covered. Offered fall semester of odd-numbered years in which Visual Programming is not being offered. Prerequisite: APCS 201","offering":"Offered fall semester of odd-numbered years in which Visual Programming is not being offered.","sourcePage":119},"APCS 242":{"code":"APCS 242","title":"Computer & Network Management","credits":"3","description":"Students will determine computer performance based on evaluation of component specifications and analysis. Design and management of computer systems will be covered. Fundamentals of networking include OSI communications model, network device operation such as switching and routing. The use of AI and security measures will be covered as they apply to computer and network systems. Lab fee required. Offered fall semester. Prerequisite: LDRS 105","offering":"Offered fall semester.","sourcePage":119},"APCS 255":{"code":"APCS 255","title":"Testing & Quality Assurance","credits":"3","description":"A comprehensive study of software testing in traditional structured and unstructured environments using Quality Assurance principles. Students will learn how to improve and control the test process and assess results and learn effective ways of automating test execution in a structured way both manually and using AI Tooling. Offered every third semester. Lab fee required. Prerequisite: APCS 201","offering":"Offered every third semester.","sourcePage":120},"APCS 265":{"code":"APCS 265","title":"System Analysis and Design Methods","credits":"3","description":"Emphasis on structured analysis & design including the systems development life cycle and agile methodologies. Includes fact finding techniques, data flow diagrams, entity/relationship diagrams, case tools, feasibility analysis, input/output design, user interface design, prototyping, file and database design. Students will get experience with AI Assisted Analysis and Design Programs. Offered spring semester. Same as BUSI 265 Prerequisites: LDRS 105 and either APCS 201 or BUSI 130 or consent of the instructor","offering":"Offered spring semester.","sourcePage":120},"APCS 305":{"code":"APCS 305","title":"Programming Techniques","credits":"1","description":"Emphasis on problem classification and selection of appropriate problem-solving techniques including algorithm and data structures. Laboratory sessions involving application to “real-life” problems. Includes in- depth discussion of using artificial intelligence in the problem-solving process. Offered fall semester of even years. Lab fee required. Prerequisite: APCS 201 or consent of instructor","offering":"Offered fall semester of even years.","sourcePage":120},"APCS 306":{"code":"APCS 306","title":"Introduction to Data Science","credits":"3","description":"An introduction to techniques for analyzing data to gain insight, draw conclusions, and make decisions. Topics include data visualization, probability and statistics, linear regression, time series analysis, Monte Carlo simulation, data mining, ethics and the relationship between data science and artificial intelligence. Students will also gain experience using a popular programing language for data analytics such as Python or R. lab fee required. Offered fall semester of even-numbered years. Prerequisites: APCS 206, MATH 220 or higher.","offering":"Offered fall semester of even-numbered years.","sourcePage":120},"APCS 311":{"code":"APCS 311","title":"Networking","credits":"3","description":"Networking concepts including switching and routing concepts are covered as well as the design and management of a network system. The setup and use of virtual machines will be included. The use of AI will be covered as it applies to networking. Offered every third semester. Lab fee required. Prerequisite: APCS 220 or consent of instructor.","offering":"Offered every third semester.","sourcePage":121},"APCS 312":{"code":"APCS 312","title":"Operating Systems","credits":"3","description":"System software operation which includes the evaluation of processes, memory, files and I/O devices will be covered. A comparison of management schemes will be applied to Windows and Linux. The use of AI will be covered as it applies to operating systems, servers, and server security. Offered every third semester. Lab fee required. Prerequisite: APCS 220 or consent of instructor.","offering":"Offered every third semester.","sourcePage":121},"APCS 321":{"code":"APCS 321","title":"The Internet of Things","credits":"3","description":"The course will cover IoT business and engineering principles, electronic and embedded systems, networking protocols, security, fog and cloud integration, simple data analytics, and DSP techniques. Students will apply the IoT concepts in the development of an IoT project prototype. The use of AI will be covered as it applies to IoT operations, including security. Offered every third semester. Lab fee required. Prerequisite: APCS 220, APCS 311, and INDU227 recommended or consent of instructor.","offering":"Offered every third semester.","sourcePage":121},"APCS 326":{"code":"APCS 326","title":"Database Management Systems","credits":"3","description":"Emphasis on database systems used for management information. Examines relational databases and provides concepts for design, development, and implementation of database management information systems. Topics include normalization, SQL, comparison of different database models, backup and recovery, security, and development of an information system. Two lectures and one lab session per week. Offered fall semester. Same as BUSI 326 Prerequisites: APCS 114 or APCS 265; Junior standing recommended","offering":"Offered fall semester.","sourcePage":121},"APCS 336":{"code":"APCS 336","title":"Web Programming","credits":"3","description":"Introduction to range of programming and data management tools in the context of full-stack web application development. Students will become familiar with web development concepts and terminology. Web programming, database design and setup are integrated with design techniques and project management to give the student firsthand experience with live website development. Some hands-on experience with software such as Apache, PHP, MySQL, and specialized text editors. Lab fee required. Offered spring semester. Prerequisite: APCS 201","offering":"Offered spring semester.","sourcePage":121},"APCS 344":{"code":"APCS 344","title":"Training Practicum","credits":"1","description":"Experience designing and conducting user training sessions in conjunction with Information Services. May include application software, operating systems or Internet usage. Offered fall of odd-numbered years. Prerequisite: LDRS 105, 3 hours of APCS coursework, and junior standing","offering":"Offered fall of odd-numbered years.","sourcePage":121},"APCS 345":{"code":"APCS 345","title":"Numerical Analysis Methods","credits":"3","description":"Techniques for curve fitting, interpolation, numerical differentiation and integration; solutions of equations and systems of linear equations; polynomial approximation; error analysis, statistics and eigenvectors. Emphasis on the development of mathematical algorithms and data analysis techniques for solving problems encountered by engineers and scientists. Includes discussion of using artificial intelligence in the problem- solving process. Some solutions will be implemented in a programming environment such as MATLAB. Lab fee required. Offered every spring semester. Same as MATH 345. Prerequisites: MATH 241 and APCS 201","offering":"Offered every spring semester.","sourcePage":122},"APCS 346":{"code":"APCS 346","title":"Information & Security Assurance","credits":"3","description":"Information security, concepts, practice and policy will be covered including the auditing of network systems. Data security concepts such as cryptography and integrity will be discussed. Computer system security concepts such as authentication, authorization and accounting management techniques will be covered. Software security, network security and Internet security management techniques will be discussed. The use of AI to manage Cybersecurity operations will be covered. Open labs. Offered every third semester. Lab fee required. Prerequisite: APCS 311 or consent of instructor.","offering":"Offered every third semester.","sourcePage":122},"APCS 350":{"code":"APCS 350","title":"Data Structures & Algorithm Analysis","credits":"3","description":"Emphasis on fundamental data structures including strings, stacks, queues, lists, graphs, trees, and heaps. Includes order of magnitude analysis of algorithms, object-oriented programming, searching and sorting methods, and concepts of software engineering for large scale projects. Three lectures and one lab session per week. Offered fall semester of odd-numbers years. Lab fee required. Prerequisites: APCS 206, APCS 220; MATH 212 recommended","offering":"Offered fall semester of odd-numbers years.","sourcePage":122},"APCS 357":{"code":"APCS 357","title":"Internship","credits":"1-6","description":"Extensive work experience in an area related to student’s major field of concentration under the direct supervision of a regular faculty member and an on-site work supervisor. Approval of the faculty member, work supervisor, and division chair must be secured in advance of registration. This course may be taken more than once, for up to a total of 6 hours maximum credit per declared major. University guidelines specify a student must perform a minimum of 40 hours of meaningful work per credit hour earned. The division chair will oversee all internships credits.","offering":"","sourcePage":122},"APCS 360":{"code":"APCS 360","title":"and other sources). Student teams will use industry best practice tools, methodologies, and policies","credits":"","description":"to successfully interact with team members, stakeholders, and vendors to implement a technology project. Students will use AI enabled tooling for design and implementation of the project. Offered spring semester. Lab fee required. Prerequisite: APCS 360 or consent of instructor","offering":"Offered spring semester.","sourcePage":123},"APCS 370":{"code":"APCS 370","title":"Systems Implementation","credits":"3","description":"Student-led team projects focus on creating solutions from proposals, designs, and prototypes (derived from","offering":"","sourcePage":123},"APCS 390":{"code":"APCS 390","title":"Professional Development Seminar","credits":"2","description":"Readings and discussion of professional and ethical issues; preparation of an individual’s professional portfolio. Participation in a professional meeting and presentation of a paper based on original research and/or ideas encountered at the meeting. Students will focus on current and advanced technology topics such as Artificial Intelligence. Offered spring semester. Lab fee required. Same as INDU/MATH/PHYS 390 Prerequisite: Junior standing in APCS or consent of instructor","offering":"Offered spring semester.","sourcePage":123},"APCS 395":{"code":"APCS 395","title":"Professional Development Seminar II","credits":"1","description":"Continuation of professional development in a second area. Preparation of a professional portfolio; presentation of an individual research project or participation in another professional meeting and presentation of a research paper. Pre/Co-requisite APCS/MATH/PHYS 390","offering":"","sourcePage":123},"ART 116":{"code":"ART 116","title":"Painting I—Studio Art Class","credits":"3","description":"Introduction to basic painting techniques and styles of painting, including abstract, impressionism, surrealism, and others. Students will work with various types of brushes, masking techniques, under-painting, paints, and surfaces. Offered fall semester of odd years. Lab fee required.","offering":"Offered fall semester of odd years.","sourcePage":123},"ART 117":{"code":"ART 117","title":"Pen and Ink Drawing—Studio Art Class","credits":"3","description":"Emphasis on pen and ink techniques including but not limited to calligraphy, stippling, contour, parallel and crosshatching on various papers and boards. A varied subject matter will provide students the opportunity to learn shading and dimensional effects. Offered fall semester of even years. Lab fee required.","offering":"Offered fall semester of even years.","sourcePage":123},"ART 121":{"code":"ART 121","title":"Drawing I—Studio Art Class","credits":"3","description":"Drawing in various media including pencil, charcoal, conte, pastel, and pen and ink. Subjects include still life, models, landscape, and animals. Offered every fall. Lab fee required.","offering":"Offered every fall.","sourcePage":123},"ART 130":{"code":"ART 130","title":"Three-Dimensional Design—Studio Art Class","credits":"3","description":"An introduction to 3-D design principles and exploration of a variety of media. Offered fall of odd years. Lab fee required.","offering":"Offered fall of odd years.","sourcePage":123},"ART 134":{"code":"ART 134","title":"Two-Dimensional Design—Studio Art Class","credits":"3","description":"Principles of design, the creative process, and applying basic formats and theories in simple design and projects. Analysis of design and compositional elements. Principles of color theories. Emphasis on line drawings, marker renderings, perspective concepts, and basic drawing skills. Introduction to personal computer tools such as image manipulation and vector-based illustration software. Lab fee required. Offered every fall.","offering":"Offered every fall.","sourcePage":124},"ART 211":{"code":"ART 211","title":"Digital Photography—Studio Art Class","credits":"3","description":"This beginning photography course will introduce students to the basic technical concepts and photographic composition principles. The course will also cover photo editing software and standard optimization and compositing techniques. Visual storytelling through photojournalism and writing compelling cutlines will also be taught. Same as COMM 211","offering":"","sourcePage":124},"ART 215":{"code":"ART 215","title":"History of Art","credits":"3","description":"An art historical introduction to field methodologies and the effects of scholarship on the discipline. The course covers scholarship as it chronologically develops from Winkelmann to Panofsky. Offered fall even years","offering":"","sourcePage":124},"ART 217":{"code":"ART 217","title":"Painting II—Studio Art Class","credits":"3","description":"Various techniques and styles of painting are explored. Watercolor, oil, and acrylic paint are practiced in the creation of works of art. Subject matter includes but is not limited to portraiture, landscape, still life, abstract design. Lab fee required. Prerequisite: ART 116","offering":"","sourcePage":124},"ART 221":{"code":"ART 221","title":"Drawing II—Studio Art Class","credits":"3","description":"Introduction to drawing mediums pastel (oil and chalk), pen and ink, and other. Subject matter includes life (portrait, landscape), abstraction, calligraphy, and other. If ART 121 has not been taken, instructor permission is necessary. Lab fee required.","offering":"","sourcePage":124},"ART 230":{"code":"ART 230","title":"Sculpture—Studio Art Class","credits":"3","description":"Introduces the development of sculptural concepts and objects through history, techniques and processes using basic three-dimensional materials, including clay, plaster, cardboard, and found objects.","offering":"","sourcePage":124},"ART 235":{"code":"ART 235","title":"Graphic Art—Studio Art Class","credits":"3","description":"Lecture and lab will develop a solid base in technical and creative skills utilizing the latest personal computer tools. Emphasis on design of logos, typography and type as a design element, packaging materials, continuous page layout, and grid design. Emphasis on the design process of digitally produced materials, developed in stages from roughs and overlays to presentations of illustrations, advertisements, and brochures. Will use Adobe image manipulation software, vector-based illustration software, and specialized computer graphic tools to integrate images and type in producing posters, signage, direct mail advertisements, and advertising. Lab fee required. Offered every spring. Prerequisite: LDRS 105, ART 134","offering":"Offered every spring.","sourcePage":124},"ART 331":{"code":"ART 331","title":"Ceramics I—Studio Art Class","credits":"3","description":"Fundamentals of pottery including terminology, hand-building processes, and wheel methods with projects in pinch, coil, slab, sculpture, and wheel work. Lab fee required. Prerequisite: Sophomore standing","offering":"","sourcePage":125},"ART 332":{"code":"ART 332","title":"Ceramics II—Studio Art Class","credits":"3","description":"Further development of basic techniques with special emphasis on wheel work. Advanced decorating and throwing methods, fundamentals of glaze making, and firing will be presented. Lab fee required. Prerequisite: ART 331","offering":"","sourcePage":125},"BIOL 101":{"code":"BIOL 101","title":"General Biology I","credits":"4","description":"An exploration of the diversity of life including bacteria, protists, plants, fungi, and animals; the nature of heredity; evolution; and principles of ecology. Fulfills Liberal Arts Core requirement for Laboratory Science. Three lectures and one lab period per week. Offered in the fall semester.","offering":"Offered in the fall semester.","sourcePage":125},"BIOL 102":{"code":"BIOL 102","title":"General Biology II","credits":"4","description":"Describes the basis of life, from molecules, cells, and genes to the form and function of microbial, plant, and animal systems. Intended for biology and exercise science majors. Recommended for those who are seeking entry to professional health-care programs or those who are interested in pursuing additional study beyond","offering":"","sourcePage":125},"BIOL 111":{"code":"BIOL 111","title":"Environmental Biology","credits":"3","description":"An introduction to the study of the environment, with an emphasis on studying interrelationships between ecosystems, geological systems, and social systems. This course includes lecture, lab, field, and service components.","offering":"","sourcePage":125},"BIOL 150":{"code":"BIOL 150","title":"Biology Field Trip","credits":"1","description":"A three- to seven-day excursion to experience first- hand the variety of geological and biological systems present in the central United States. Pre- or post-course discussion and research papers may be required. Course may be repeated up to three times. Lab fee required. Same as EASC 150","offering":"","sourcePage":125},"BIOL 202":{"code":"BIOL 202","title":"Medical & Scientific Terminology","credits":"2","description":"Familiarizes students with terminology used in medicine and biology. Includes study of roots, prefixes, and suffixes derived from Latin and Greek as well as basic terms dealing with anatomy, diseases, and medical procedures.","offering":"","sourcePage":126},"BIOL 216":{"code":"BIOL 216","title":"Anatomy and Physiology","credits":"4","description":"A course designed for non-biology majors that study the structure and function of the human body. Includes how the various systems of the body work with homeostasis. Three lectures and one lab per week.","offering":"","sourcePage":126},"BIOL 220":{"code":"BIOL 220","title":"Vertebrate Fauna","credits":"4","description":"Examines the natural history, behavior, form, and function of vertebrates, emphasizing Midwestern forms. Three lectures and one lab session per week. Prerequisites: BIOL 102 or consent of instructor","offering":"","sourcePage":126},"BIOL 225":{"code":"BIOL 225","title":"General Botany","credits":"4","description":"Introduction to the basic concept of Plant Biology. Among the topics covered are: plant physiology, plant cells and tissues, cell division, reproduction, genetics, development, anatomy, plant diversity and systematics, and evolution. Three lectures and one lab per week.","offering":"","sourcePage":126},"BIOL 300":{"code":"BIOL 300","title":"Natural Science Seminar","credits":"1","description":"Discussion of journal/periodical resources in the student’s chosen area, performance and presentation of small independent laboratory project, participation in a school-sponsored academic event or in a professional meeting. Same as CHEM 300, EASC 300 Prerequisite: junior or senior standing","offering":"","sourcePage":126},"BIOL 304":{"code":"BIOL 304","title":"Plant Taxonomy and Local Flora","credits":"4","description":"Study of the taxonomy and systematics of the vascular plants and identification of the common plants of the Midwest. Three lectures and one lab session per week. Prerequisite: BIOL 102","offering":"","sourcePage":126},"BIOL 307":{"code":"BIOL 307","title":"General Ecology","credits":"4","description":"Includes an introduction to experimental design and interpretation. Studies relationship between organisms and their natural environment. Some mathematical skill helpful. Emphasis on Midwestern ecosystems. Three lectures and one lab session per week. Prerequisite: BIOL 102 or consent of instructor","offering":"","sourcePage":126},"BIOL 308":{"code":"BIOL 308","title":"Microbiology","credits":"4","description":"Application of microbiological techniques for study of microorganisms including aspects of bacteriology, immunology, and virology. Three lectures and one lab session per week. Offered in the fall semester. Prerequisite: CHEM 101 or consent of instructor","offering":"Offered in the fall semester.","sourcePage":126},"BIOL 313":{"code":"BIOL 313","title":"Comparative Anatomy","credits":"4","description":"Provides Information about the structures that make up bodies of humans and other vertebrates and discusses how they are used and modified for the survival of the organism. Emphasizes dissection as an important method of learning about animal structures. Three lectures and one lab sessions per week. Prerequisite: BIOL 101 and BIOL 102 or consent of instructor","offering":"","sourcePage":127},"BIOL 314":{"code":"BIOL 314","title":"Human Anatomy","credits":"4","description":"Provides a comprehensive introduction to the structures of the human body. All the major body systems are covered, with additional units on histology and developmental anatomy. Coursework emphasizes animal dissection and the use of human models. Prerequisite: BIOL 101 and BIOL 102 or consent of instructor","offering":"","sourcePage":127},"BIOL 315":{"code":"BIOL 315","title":"Physiology","credits":"4","description":"Deals with the functions and regulatory mechanisms of animal organ systems, with a primary emphasis on humans. Three lectures and one lab session per week. Prerequisites: CHEM 101 and BIOL 313 or 314, or consent of instructor","offering":"","sourcePage":127},"BIOL 322":{"code":"BIOL 322","title":"Medical Biology","credits":"3","description":"An investigation into the medical aspects of the five kingdoms of life, as well as viruses, exploring the roles of organisms in human health, disease, medicines and medical modeling. Includes an introduction to experimental design and interpretation. Prerequisites: BIOL 101, BIOL 102 or consent of instructor","offering":"","sourcePage":127},"BIOL 335":{"code":"BIOL 335","title":"Genetics","credits":"4","description":"Teaches students to analyze the inheritance of traits of various organisms and to understand the molecular and cellular basis of inheritance. Three lectures and one lab session per week. Prerequisite: BIOL 308 or consent of instructor","offering":"","sourcePage":127},"BIOL 341":{"code":"BIOL 341","title":"Developmental Biology","credits":"4","description":"Describes the embryonic development of organisms and deals with the experimental analysis of cause and effect during development. Two lectures and one lab session per week. Prerequisites: BIOL 313 or 314, and BIOL 335, or consent of instructor","offering":"","sourcePage":127},"BIOL 343":{"code":"BIOL 343","title":"Immunology","credits":"4","description":"This upper-level course will survey the function of the immune system in health and disease. Topics will include lymphocyte function, immune control, and medical aspects of immunity. It will be taught using a collaborative team- based approach including laboratory work and analysis of papers from the scientific literature. Prerequisites: BIOL 315, BIOL 335","offering":"","sourcePage":127},"BIOL 345":{"code":"BIOL 345","title":"Biochemistry","credits":"4","description":"A study of the basic biochemical pathways found in living systems. Emphasis will be on molecular genetics, protein synthesis, carbohydrate metabolism, and photosynthesis. Three lectures and one lab session per week. Offered in the spring semester. Same as CHEM 345 Prerequisite: CHEM 201 or consent of instructor","offering":"Offered in the spring semester.","sourcePage":128},"BIOL 356":{"code":"BIOL 356","title":"Pre-Internship","credits":"1","description":"This course will prepare students for an internship in a subsequent semester. Topics/activities include: Employer expectations, workplace etiquette, workplace attire, workplace behavior, resume and cover letter writing, mock- interviews. Culmination of course is an interview with a prospective employer with the aim of securing an internship position. Failure to obtain internship position will preclude registration for BIOL 357.","offering":"","sourcePage":128},"BIOL 357":{"code":"BIOL 357","title":"Internship","credits":"1-6","description":"Extensive work experience in an area related to student’s major field of concentration under the direct supervision of a regular faculty member and an on-site work supervisor. Approval of the faculty member, work supervisor, and division chair must be secured in advance of registration. This course may be taken more than once, for up to a total of 6 hours maximum credit per declared major. University guidelines specify a student must perform a minimum of 40 hours of meaningful work per credit hour earned. The division chair will oversee all internships credits. Prerequisite: BIOL/KINS 356","offering":"","sourcePage":128},"BIOL 390":{"code":"BIOL 390","title":"Biology Practicum","credits":"1","description":"A capstone course to allow students to integrate the knowledge and skills they have obtained in the study of Biology. One hour offered in the fall semester and one hour offered in the spring semester. Two credits required for biology core. Prerequisite: Junior or Senior standing.","offering":"","sourcePage":128},"BUSI 130":{"code":"BUSI 130","title":"Contemporary Business","credits":"3","description":"Overview of the foundations of business including, but not limited to, business ethics, terms of ownership, management, organization, production, human resources, finance, and marketing. The case-study method of analysis also will be introduced. Offered every spring.","offering":"Offered every spring.","sourcePage":128},"BUSI 201":{"code":"BUSI 201","title":"Principles of Accounting I","credits":"","description":"3 credit hours Concepts and issues of financial accounting as a system of recording, classifying, summarizing, and interpreting business transactions for preparing financial reports. Offered every fall. Prerequisite: Sophomore standing or consent of instructor.","offering":"Offered every fall.","sourcePage":128},"BUSI 202":{"code":"BUSI 202","title":"Principles of Accounting II","credits":"3","description":"A continuation of Principles of Accounting I with an emphasis on financial analysis and reporting to aid management in decision making. Offered every spring. Prerequisite: BUSI 201","offering":"Offered every spring.","sourcePage":129},"BUSI 204":{"code":"BUSI 204","title":"Understanding Financial Accounting Information","credits":"3","description":"This course will provide an understanding of financial information, using a proven non-debit/credit approach that emphasizes the decision-usefulness of accounting information and de-emphasizes mechanical procedures, enabling students to be effective decision makers and business leaders. This course evaluates the effects of economic events on the balance sheet and the income statement, as well as budget preparation and monitoring.","offering":"","sourcePage":129},"BUSI 230":{"code":"BUSI 230","title":"Principles of Management","credits":"3","description":"Introduction to the management discipline designed to provide a basic understanding of both theory and practice encompassing the planning, organizing, staffing, directing, and controlling functions. Offered every semester. Prerequisite: LDRS 102; BUSI 130 recommended","offering":"Offered every semester.","sourcePage":129},"BUSI 240":{"code":"BUSI 240","title":"Entrepreneurship and Innovation","credits":"3","description":"This course is designed to instruct students on the process of formulating, planning, and implementing a new venture. Students are exposed to detailed descriptions of ‘how to’ embark on a new venture in a logical manner. The final project will be a business plan that could serve a new venture or significant new product line to an existing organization. Offered every fall. Prerequisites: BUSI 230 and Junior standing.","offering":"Offered every fall.","sourcePage":129},"BUSI 246":{"code":"BUSI 246","title":"Consumer Behavior and Research","credits":"3","description":"This course is an introduction to the world of consumer behavior, building a strong foundation and practical focus on real-world applications for today's global business environment. Cutting-edge research and current business practices are featured, including coverage of social media influences, increased consumer power, and emerging neuroscience findings, with an increased emphasis on social responsibility and ethics in marketing. Offered every fall. Prerequisite: LDRS 105","offering":"Offered every fall.","sourcePage":129},"BUSI 265":{"code":"BUSI 265","title":"Systems Analysis and Design Methods","credits":"3","description":"Emphasis on structured analysis & design including the systems development life cycle. Includes fact finding techniques, data flow diagrams, entity/relationship diagrams, case tools, feasibility analysis, input/output design, user interface design, prototyping, file and database design. Same as APCS 265 Prerequisites: LDRS 105 and either APCS 201 and APCS 206 or BUSI 130 or consent of the instructor.","offering":"","sourcePage":129},"BUSI 270":{"code":"BUSI 270","title":"Accounting Software Applications","credits":"3","description":"Emphasizes application of computerized financial software commonly used in small businesses. Topics include recording receivables, inventory, payables, payroll, banking activities, jobs and time tracking, and the accounting cycle. Offered every spring.","offering":"Offered every spring.","sourcePage":130},"BUSI 301":{"code":"BUSI 301","title":"Intermediate Accounting I","credits":"3","description":"Basic accounting theory relating to income measurement and asset valuation. Special emphasis on the problems, principles and concepts of accounting for assets and liabilities under current generally accepted accounting principles. Offered every fall. Prerequisite: BUSI 202","offering":"Offered every fall.","sourcePage":130},"BUSI 302":{"code":"BUSI 302","title":"Intermediate Accounting II","credits":"3","description":"Special problems, principles and concepts relating to financial accounting for stockholders’ equity, investments and income determination. Preparation and analysis of financial statements. Offered every spring. Prerequisite: BUSI 301","offering":"Offered every spring.","sourcePage":130},"BUSI 305":{"code":"BUSI 305","title":"Managerial Cost Accounting I","credits":"3","description":"Conceptual and technical aspects of cost accounting. Theories of cost control over products, projects and segments of a business. Uses of management accounting information for budgeting and profit planning. Offered fall of odd years. Prerequisite: BUSI 202","offering":"Offered fall of odd years.","sourcePage":130},"BUSI 306":{"code":"BUSI 306","title":"Managerial Cost Accounting II","credits":"3","description":"Special problems, principles and concepts relating to cost accounting systems as a tool for planning and control. Issues relating to systems design and the behavioral implications of budgeting and management reporting. Offered spring of even years. Prerequisite: BUSI 305","offering":"Offered spring of even years.","sourcePage":130},"BUSI 309":{"code":"BUSI 309","title":"Business Law","credits":"3","description":"Principles and concepts of business law. Acquaints the student with the legal environment of business; with an emphasis on contracts and the Uniform Commercial Code, agency, employment law, business organization and government regulation. Offered every fall. Prerequisite: Junior standing or consent of instructor.","offering":"Offered every fall.","sourcePage":130},"BUSI 310":{"code":"BUSI 310","title":"Commercial Law","credits":"3","description":"Principles and rules of commercial law. Acquaints the student with the legal environment of business; emphasis on contracts, sales, and the Uniform Commercial Code and commercial paper. Offered every fall. Prerequisite: Junior standing or consent of instructor.","offering":"Offered every fall.","sourcePage":131},"BUSI 311":{"code":"BUSI 311","title":"Contemporary Business Law","credits":"3","description":"Legal issues and concerns for business managers. Topics include debtor-creditor relationships; agency and forms of business organization; employment, environmental, and consumer law; antitrust; intellectual property. Offered every spring. Prerequisite: Junior standing or consent of instructor.","offering":"Offered every spring.","sourcePage":131},"BUSI 314":{"code":"BUSI 314","title":"Federal Income Tax I","credits":"3","description":"Survey of the internal revenue code and the regulations relating to income, exclusions from income, deductions and credits in computing federal income tax liability for individuals and corporations. Offered fall of even years. Prerequisite: BUSI 202 or consent of instructor.","offering":"Offered fall of even years.","sourcePage":131},"BUSI 315":{"code":"BUSI 315","title":"Federal Income Tax II","credits":"3","description":"Principles and theories of the internal revenue code relating to corporations and partnerships. Income tax implications and concerns for management planning and decision-making. Offered spring of odd years. Prerequisite: BUSI 314","offering":"Offered spring of odd years.","sourcePage":131},"BUSI 321":{"code":"BUSI 321","title":"Sports Marketing","credits":"3","description":"Marketing concepts applied to the sports industry with application emphasis on the amateur and collegiate levels. Topics covered include the traditional marketing mix, services marketing, public relations, and event planning. Students also will utilize case studies and individual and team projects in learning how to market sporting events. Same as SMGT 321 Prerequisite: Junior standing or consent of instructor.","offering":"","sourcePage":131},"BUSI 324":{"code":"BUSI 324","title":"E-Commerce","credits":"3","description":"Presents concepts and skills for the strategic use of e-commerce and related information technology from three perspectives: business to consumers, business-to-business, and intra-organizational. Examination of e- commerce in altering the structure of entire industries, and how it affects business processes. Students gain an understanding of the dynamics within this fast-paced industry balancing technological issues with the strategic business aspects of successful e-commerce including an examination of social media and online marketing strategies, technology-enabled outsourcing, and online payment processing systems. Offered spring. Prerequisites: LDRS 105, Junior standing.","offering":"Offered spring.","sourcePage":131},"BUSI 326":{"code":"BUSI 326","title":"Database Management Systems","credits":"3","description":"Emphasis on database systems used for management information. Examines relational databases and provides concepts for design, development, and implementation of database management information systems. Topics include normalization, SQL, comparison of different database models, backup and recovery, security, and development of an information system. Two lectures and one lab session per week. Same as APCS 326 Prerequisites: APCS 114; Junior standing recommended.","offering":"","sourcePage":131},"BUSI 328":{"code":"BUSI 328","title":"Small Business Finance","credits":"3","description":"This course will introduce financial thinking, tools, and techniques adapted to the realm of small business management and entrepreneurship. Small Business Finance introduces the theories, knowledge, financial tools, and sound management practices a small business owner or entrepreneur needs to start, build, and maintain a successful venture. Offered every spring. Prerequisites: LDRS 105, BUSI 201","offering":"Offered every spring.","sourcePage":132},"BUSI 330":{"code":"BUSI 330","title":"Small Business Management","credits":"3","description":"Starting and managing a small business is centered around a business plan, including formulation of a business idea, assessing the market potential, selecting a location, selecting a legal form of organization, arranging financing, securing necessary supplies, meeting governmental regulations, securing and retaining appropriate employees, instituting accounting records, establishing appropriate controls. Prerequisites: LDRS 105, BUSI 201","offering":"","sourcePage":132},"BUSI 332":{"code":"BUSI 332","title":"Operations Management","credits":"3","description":"Study of the operations environment including production methods, scheduling, inventory control, facility location and layout, quality concerns, materials management, and JIT philosophies. Offered every fall. Prerequisites: BUSI 230 and junior standing; MATH 220 recommended.","offering":"Offered every fall.","sourcePage":132},"BUSI 334":{"code":"BUSI 334","title":"Marketing Management","credits":"3","description":"Introduction to the ways in which companies plan, price, promote, and place their goods and services to present and potential customers. Offered every spring. Prerequisite: Junior standing or consent of instructor","offering":"Offered every spring.","sourcePage":132},"BUSI 336":{"code":"BUSI 336","title":"Human Resource Management","credits":"3","description":"Study of the organization, selection, development, compensation, and utilization of the human resources of the firm; also surveys labor-management relations and development. Offered every fall. Prerequisite: Junior standing or consent of instructor; BUSI 230 recommended","offering":"Offered every fall.","sourcePage":132},"BUSI 338":{"code":"BUSI 338","title":"Financial Management","credits":"3","description":"Introduction to corporate financial planning and tools of financial analysis which may be used to manage working capital, administer capital budgeting, and evaluate the capital structure of a profit-oriented firm. Offered every fall. Prerequisites: BUSI 202, and Junior standing; MATH 220 recommended.","offering":"Offered every fall.","sourcePage":132},"BUSI 345":{"code":"BUSI 345","title":"Organizational Behavior","credits":"","description":"3 credit hours Analysis of the behavior of people in organizations, drawing upon the disciplines of Psychology, Sociology, and Business Administration. Applications are studied in the context of effective management of organizational behavior and the important interrelationships between needs and expectations of the individual, the organization, and society. Offered every fall. Same as SOCI 345 Prerequisite: Junior standing or consent of instructor","offering":"Offered every fall.","sourcePage":132},"BUSI 347":{"code":"BUSI 347","title":"Business Ethics","credits":"3","description":"Approaches to ethical issues and problems facing business and society today. Offered fall and spring. Same as SOCI 347 Prerequisite: Junior standing","offering":"Offered fall and spring.","sourcePage":133},"BUSI 349":{"code":"BUSI 349","title":"International Business","credits":"3","description":"Study of business in a global economy with the major complexities involved including the effects of different social systems, governmental influences on trade, financial exchange rates, and corporate relationships and policies. Offered every spring. Same as ECON/PLSC 349 Prerequisite: Junior standing","offering":"Offered every spring.","sourcePage":133},"BUSI 353":{"code":"BUSI 353","title":"Advanced Accounting I","credits":"3","description":"A special topics course which includes an advanced treatment of the accounting problems of partnerships and business combinations. Consolidated financial statements will be studied, and fund accounting will be considered. Offered every fall. Prerequisite: BUSI 302","offering":"Offered every fall.","sourcePage":133},"BUSI 354":{"code":"BUSI 354","title":"Advanced Accounting II","credits":"3","description":"Topics include accounting and reporting for bankruptcy, estates and trusts, multinational enterprises, segments, interim reports, SEC reporting, installment sales and consignments. Offered every spring. Prerequisite: BUSI 353","offering":"Offered every spring.","sourcePage":133},"BUSI 355":{"code":"BUSI 355","title":"Auditing","credits":"3","description":"Concepts, fundamentals and techniques of verification of balance sheet and income statement accounts, evaluation of the system of internal control including E.D.P. systems and uses of statistical sampling. Viewed from the standpoint of the certified public accountant in rendering an audit opinion. Offered every fall. Prerequisite: BUSI 302","offering":"Offered every fall.","sourcePage":133},"BUSI 357":{"code":"BUSI 357","title":"Business Internship","credits":"1 - 6","description":"A work experience project, initiated by the student and approved by a faculty supervisor, which allows the student to learn and practice business skills. During the project, the student will submit written reports on the work experience to the faculty supervisor. Application for approval of a project must be made in writing to the faculty supervisor, including a statement of the proposed length of time of work experience, the name of the firm providing employment, the name of the work supervisor on the job, and a description of the work to be done. Each hour of academic credit requires (verified) completion of 60 hours on the job. Offered every semester.","offering":"Offered every semester.","sourcePage":133},"BUSI 460":{"code":"BUSI 460","title":"Corporate Strategy","credits":"3","description":"Examines the total business organization and its environment from the perspective of executive management. Attention given to discerning and framing objectives, strategies, and their implementation; management simulation and analysis of business situations through the case-study method are utilized. In this capstone course, students will integrate concepts learned in previous management courses. Offered every spring. Prerequisite: Senior standing in a Business Administration major","offering":"Offered every spring.","sourcePage":134},"BUSI 463":{"code":"BUSI 463","title":"C.P.A. Review","credits":"3","description":"Accounting review and approaches to solutions for problems and questions in the CPA examinations. Tutorial fee required. Offered with sufficient demand. Prerequisite: Qualified to sit for CPA exams.","offering":"Offered with sufficient demand.","sourcePage":134},"CHEM 101":{"code":"CHEM 101","title":"General Chemistry I","credits":"4","description":"Selected principles, theories, laws, and applications of chemistry as a means of understanding common experiences of a chemical nature. Exploratory, descriptive and experimental study of the behavior and interaction of the more common chemical substances. Three lectures and one lab session per week. Offered in the fall semester. Prerequisite: MATH 140 or consent of instructor","offering":"Offered in the fall semester.","sourcePage":134},"CHEM 102":{"code":"CHEM 102","title":"General Chemistry II","credits":"4","description":"Continuation of general chemistry principles. Three lectures and one lab session per week. Offered in the spring semester. Prerequisite: CHEM 101 or consent of instructor","offering":"Offered in the spring semester.","sourcePage":134},"CHEM 201":{"code":"CHEM 201","title":"Organic Chemistry I","credits":"4","description":"Chemistry of carbon compounds, preparation sources, uses, and laboratory techniques. Three lectures and one lab session per week. Offered in the fall semester. Prerequisite: CHEM 102 or consent of instructor","offering":"Offered in the fall semester.","sourcePage":134},"CHEM 202":{"code":"CHEM 202","title":"Organic Chemistry II","credits":"4","description":"Continuation of Chemistry 201. Three lectures and one lab session per week. Offered in the spring semester. Prerequisite: CHEM 201 or consent of instructor","offering":"Offered in the spring semester.","sourcePage":134},"CHEM 223":{"code":"CHEM 223","title":"Quantitative Analysis","credits":"4","description":"Solution equilibria, fundamentals of volumetric and gravimetric analysis. Two lectures and two lab sessions per week. Offered on demand. Prerequisite: CHEM 201 or consent of instructor","offering":"Offered on demand.","sourcePage":135},"CHEM 300":{"code":"CHEM 300","title":"Natural Science Seminar","credits":"1","description":"Discussion of journal/periodical resources in the student’s chosen area, performance and presentation of small independent laboratory project, participation in a school-sponsored academic event or in a professional meeting. Same as BIOL 300 Prerequisite: Junior or Senior standing","offering":"","sourcePage":135},"CHEM 310":{"code":"CHEM 310","title":"Scanning Electron Microscopy","credits":"3","description":"The Scanning Electron Microscopy (SEM) course provides a foundation for students new to SEM and emphasizes hands-on learning. Students can study their own samples, or test samples provided by the department. During the course, students will learn through lecture, demonstration, and hands-on participation how to setup and operate SEM and EDS instruments. Objectives of the course include the ability to align an SEM, obtain secondary electron (SE) and backscatter electron (BE) micrographs, and perform EDS qualitative and quantitative analysis. The course goal is for the students to become competent, research-level scanning electron microscopists. They will understand the functions of the SEM and how it works. They will be competent in basic operating techniques, and ready to learn more advanced ones as needed. Prerequisite: Senior Standing","offering":"","sourcePage":135},"CHEM 345":{"code":"CHEM 345","title":"Biochemistry","credits":"4","description":"A study of the basic biochemical pathways found in living systems. Emphasis will be on molecular genetics, protein synthesis, carbohydrate metabolism, and photosynthesis. Three lectures and one lab session per week. Offered in the spring semester. Same as BIOL 345 Prerequisite: CHEM 201 or consent of instructor","offering":"Offered in the spring semester.","sourcePage":135},"COMM 102":{"code":"COMM 102","title":"Media Writing","credits":"3","description":"This course focuses on the basics of narrative, documentary, and informative writing styles for professional media.","offering":"","sourcePage":135},"COMM 104":{"code":"COMM 104","title":"Social Media Marketing","credits":"3","description":"In the modern professional world, the management of personal identity is an essential element in maintaining a standing in creative media. Students will learn how to use social media tools from their first days in school to not only manage their own image, but also to help sell the work they create.","offering":"","sourcePage":135},"COMM 120":{"code":"COMM 120","title":"Studio Production","credits":"3","description":"This course teaches the foundational skills necessary for successful video production, including terminology, basic camera and audio methods and techniques, composition, lighting, the basics of editing, and various video formats. The students use the studio as their lab for this course to develop safety, team work, and communication skills.","offering":"","sourcePage":136},"COMM 128":{"code":"COMM 128","title":"Audio Production","credits":"3","description":"This course covers a variety of production techniques including the function of different microphones, pick-up patterns, and acquisition of audio, and the physics of audio production. Students will learn how to use sound in a production to convey information and tell a story by using digital techniques and tools. Students will also create programming for Penn’s radio station and will work audio for various campus and off campus venues.","offering":"","sourcePage":136},"COMM 141":{"code":"COMM 141","title":"Practicum","credits":"1","description":"Students will learn techniques for covering sports, lectures, and events by analyzing professional productions and then applying those techniques to their own productions. Responsibilities may include live event camera operation, audio techniques, technical directing, directing, and producing. Mostly evening hours are required. The schedule varies depending upon events. May be repeated for credit. Offered every fall and spring.","offering":"Offered every fall and spring.","sourcePage":136},"COMM 211":{"code":"COMM 211","title":"Digital Photography","credits":"3","description":"This beginning photography course will introduce students to the basic technical concepts and photographic composition principles. The course will also cover photo editing software and standard optimization and compositing techniques. Visual storytelling through photojournalism and writing compelling cutlines will also be taught. Same as ART 211","offering":"","sourcePage":136},"COMM 221":{"code":"COMM 221","title":"Production I","credits":"3","description":"This course is tied to Production II and should be taken at the same time. A class in video photography, including the use of pre-production, lighting, basic sound, and camera positioning. Co-requisite: COMM 222","offering":"","sourcePage":136},"COMM 222":{"code":"COMM 222","title":"Production II","credits":"3","description":"This course is tied to Production I and should be taken at the same time. Computer editing systems are used to manipulate video and create special effects. Co-requisite: COMM 221","offering":"","sourcePage":136},"COMM 225":{"code":"COMM 225","title":"Digital Storytelling","credits":"3","description":"This course teaches the process of developing and propagating fiction through channels of digital distribution. It will explore new and old rules for digital storytelling and distribution. Starting with appointment blogging, moving to still image documentary, finding a sharing platform with short stories (and wattpad), and finally producing a work of fiction or non-fiction on video that adheres to the principles of storytelling presented in class.","offering":"","sourcePage":136},"COMM 235":{"code":"COMM 235","title":"Advanced Practicum","credits":"3","description":"Designed for an advanced practicum experience where students who successfully participated in the required","offering":"","sourcePage":137},"COMM 321":{"code":"COMM 321","title":"Production III","credits":"3","description":"An extension of Production I and II, this course will take a more advanced approach to production and will add emphasis on professionalization and industry-specific knowledge. Pre-Requisite: COMM 222","offering":"","sourcePage":137},"COMM 322":{"code":"COMM 322","title":"Production IV","credits":"3","description":"An extension of Production I, II and III, this course explores the artistic and technological decisions related to film production. Pre-requisite: COMM 321","offering":"","sourcePage":137},"COMM 357":{"code":"COMM 357","title":"Internship","credits":"3","description":"Students will work for employers to practice skills learned in their major. Students will be supervised by an instructor at William Penn who will structure the learning experience to the benefit of the employer and the student. (May be taken up to two times for credit.)","offering":"","sourcePage":137},"COMM 390":{"code":"COMM 390","title":"Applied Communications Seminar","credits":"3","description":"This is a preparatory capstone course for Communications majors focusing on professional development, skills and discussion of professional and ethical issues. Individual research and technology-based presentations in students’ specific disciplines in the form of a senior project will prepare students for professional positions or graduate study. Specifically, students in English, Journalism, Fine Arts, or Public Relations will learn interview skill techniques and how to prepare professional portfolios. Prerequisite: Senior standing or instructor’s consent","offering":"","sourcePage":137},"EASC 100":{"code":"EASC 100","title":"Introduction to Earth Science","credits":"3","description":"Introduces the student to the Earth’s varied environments. The course contains units on astronomy, geology, meteorology, and oceanography. Two lectures and one lab per week. Offered every fall.","offering":"Offered every fall.","sourcePage":137},"EASC 104":{"code":"EASC 104","title":"Physical Geology","credits":"4","description":"A study of physical, geological processes and their role in shaping the Earth’s surface environments. Topics include minerals, rocks, soils, weathering, volcanoes, earthquakes, and plate tectonics. Three lectures and one lab session per week.","offering":"","sourcePage":138},"EASC 128":{"code":"EASC 128","title":"Astronomy","credits":"3","description":"An introduction to astronomy in which the origin and history of the universe, life cycle of stars, and the origin and evolution of the solar system will be discussed. Includes both lecture and laboratory sessions. Offered every spring.","offering":"Offered every spring.","sourcePage":138},"EASC 150":{"code":"EASC 150","title":"Geology Field Trip","credits":"1","description":"A three- to seven-day excursion to experience first-hand the variety of geological and biological systems present in the central United States. Pre- or post-trip research and discussions may be required. Course may be taken three times for credit. Offered every fall and spring. Same as BIOL 150","offering":"Offered every fall and spring.","sourcePage":138},"EASC 300":{"code":"EASC 300","title":"Natural Science Seminar","credits":"1","description":"Discussion of journal/periodical resources in the student’s chosen area, performance and presentation of small independent laboratory projects, participation in a school-sponsored academic event or in a professional meeting. Same as BIOL 300, CHEM 300.","offering":"","sourcePage":138},"EASC 315":{"code":"EASC 315","title":"Historical Geology","credits":"4","description":"An introduction to the history of the Earth. Concepts of geology and the scientific method provide a framework for interpreting the fossil and rock record. Three lectures and one lab session per week. Offered on demand. Prerequisite: EASC 104 Economics","offering":"Offered on demand.","sourcePage":138},"ECON 111":{"code":"ECON 111","title":"Personal and Family Finance","credits":"3","description":"Financial planning regarding tax decisions, cash and credit management, major acquisitions, insurance, personal investments, retirement, and estate distribution. Offered every spring.","offering":"Offered every spring.","sourcePage":138},"ECON 211":{"code":"ECON 211","title":"Principles of Microeconomics","credits":"3","description":"The market economy functioning through demand and supply; focus on consumer decision making, firm decision making in different market structures, worker decision making, and selected microeconomic issues. Offered every fall. Prerequisite: Sophomore standing or consent of instructor","offering":"Offered every fall.","sourcePage":138},"ECON 212":{"code":"ECON 212","title":"Principles of Macroeconomics","credits":"","description":"3 credit hours National income, employment, price level, money and banking, fiscal and monetary policies, international trade and finance, and comparative economic systems. Offered every spring. Prerequisite: Sophomore standing or consent of instructor","offering":"Offered every spring.","sourcePage":138},"ECON 309":{"code":"ECON 309","title":"Managerial Economics","credits":"3","description":"Application of economic analysis to managerial decisions relating to demand forecasting, production levels, cost analysis, and product pricing. Offered every fall Prerequisite: ECON 211","offering":"","sourcePage":139},"ECON 349":{"code":"ECON 349","title":"International Business","credits":"3","description":"Study of business in a global economy with the major complexities involved including the effects of different social systems, governmental influences on trade, financial exchange rates, and corporate relationships and policies. Offered every spring. Same as BUSI/PLSC 349 Prerequisite: Junior standing","offering":"Offered every spring.","sourcePage":139},"EDSP 100":{"code":"EDSP 100","title":"Introduction to Exceptional Learners","credits":"3","description":"This general survey course presents an overview of children and adolescents with exceptionalities. Students will be introduced to the history of special education; pedagogical, curricular, and social considerations involved in educating diverse learners in the general education and special education classrooms; the MTSS process; multidisciplinary teams, and IEPs. Offered every fall and spring. Prerequisite or co-requisite (at the discretion of the professor): EDUC 100","offering":"Offered every fall and spring.","sourcePage":139},"EDSP 100FE":{"code":"EDSP 100FE","title":"Introduction to Education Field Experience","credits":"0","description":"Students will complete a 15-hour field experience and begin their education portfolios during this course. Fee required. Every fall and spring.","offering":"","sourcePage":139},"EDSP 280":{"code":"EDSP 280","title":"Collaboration Strategies","credits":"2","description":"Students will learn the strategies and dispositions necessary for maintaining communication and collaborative relationships with families, other educators, related service providers, individuals with exceptionalities, and personnel from community agencies. The elements of effective collaboration, the importance of collaborative team meetings, the role of the special education teacher as a consultant, and special education teacher as supervisor of paraprofessionals will be introduced. The importance of collaboration in the special education process is emphasized. Offered every spring. Prerequisite: EDUC 100","offering":"Offered every spring.","sourcePage":139},"EDSP 290":{"code":"EDSP 290","title":"Transition Education","credits":"2","description":"This course introduces organizations, networks and sources of services available for individuals with mild/moderate disabilities in the areas of career-vocational transition support, community and life skills. Pre- service teachers learn how to provide transition support for students as they move to post high school settings and ways to encourage decision making and full participation in the community. Every spring. Prerequisite: EDSP 100","offering":"","sourcePage":139},"EDSP 358":{"code":"EDSP 358","title":"Behavior Management","credits":"3","description":"Students will be introduced to theories of behavior, functional behavioral assessment, and behavior intervention plans. Students will learn, plan, and apply non-aversive approaches for the purpose of improving social skills, attention, and behavior. Students will evaluate and implement research-based methods for to promote a positive learning environment for all. Prerequisite: EDSP 100","offering":"","sourcePage":140},"EDSP 360":{"code":"EDSP 360","title":"Diagnosis and Treatment of Reading Difficulties Field Experience","credits":"0","description":"Students must enroll in this 20-hour field experience concurrently with EDSP 360: Diagnosis and Treatment of Reading Difficulties. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every spring Prerequisite: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDSP 360","offering":"","sourcePage":140},"EDSP 370":{"code":"EDSP 370","title":"Educational Assessment","credits":"3","description":"In this course, students focus on assessment, diagnosis and intervention evaluation of both general education students and students with disabilities. Legal provisions and guidelines for unbiased assessments and application of assessment results to individualized program development are introduced. Students will examine achievement, standardized diagnostic, informal, curriculum based, functional behavioral, and authentic assessments. They will learn the specialized vocabulary related to assessment for specific disabilities. Writing IEP’s and modifying assessments for students with special needs will also be examined. Fee required. Every fall. Prerequisite: EDSP 100","offering":"","sourcePage":140},"EDSP 385":{"code":"EDSP 385","title":"Differentiated Instruction Methods and Strategies","credits":"3","description":"Students will learn and demonstrate ways to differentiate instructional strategies and methods for diverse learning needs including, but not limited to: at-risk students, students with mild/moderate disabilities, gifted students, and/or culturally and linguistically diverse students. Accommodations to address individualized needs, collaborative/co-teaching approaches, and accessible/assistive technology will be explored. Offered every fall. Prerequisite: EDSP 100","offering":"Offered every fall.","sourcePage":140},"EDSP 390":{"code":"EDSP 390","title":"Special Education Practicum","credits":"1","description":"Students will complete 20 hours with a licensed professional in a special education setting. The student will identify curriculum, as well as strategies used in the special education classroom and write a reflective summary paper of the field experience. They will engage in observing, teaching, and helping as the supervising teacher directs. Every fall and spring. Prerequisite: EDSP 100 Prerequisite or co-requisite: EDSP 385","offering":"","sourcePage":141},"EDSP 400":{"code":"EDSP 400","title":"02 2nd 8-week Strategist I Elementary Student Teaching","credits":"7","description":"Students seeking endorsement in Special Education spend 8 weeks observing and student teaching in an elementary special education program for students with mild/moderate disabilities under the direction of the special education teacher and university supervisor. Every fall and spring. Prerequisite: Admission to Student Teaching Co-requisite: EDUC 405","offering":"","sourcePage":141},"EDSP 401":{"code":"EDSP 401","title":"02 2nd 8-Week Strategist I Secondary Student Teaching","credits":"7","description":"Students seeking endorsement in Special Education spend 8 weeks observing and student teaching in a secondary special education program for students with mild/moderate disabilities under the direction of the special education teacher and university supervisor. Every fall and spring. Prerequisite: Admission to Student Teaching Co-requisite: EDUC 403 or 404 Note: Elementary or secondary regular education and special education student teaching may be completed in the same semester. Students serve a split assignment of 8 weeks in the regular classroom assignment and 8 weeks in the special education setting. For all 8-week student teaching assignments, section 01 indicates 1st 8-weeks and section 02 indicates 2nd 8-weeks.","offering":"","sourcePage":141},"EDUC 100":{"code":"EDUC 100","title":"Introduction to Education","credits":"3","description":"This course is designed to acquaint students who plan to become elementary school teachers with the teaching profession, as well as William Penn University Education Division policies and procedures. Every fall and spring.","offering":"","sourcePage":141},"EDUC 100FE":{"code":"EDUC 100FE","title":"Introduction to Education Field Experience","credits":"","description":"Students will complete a 15-hour field experience in a general education setting during this course. Fee required. Every fall and spring.","offering":"","sourcePage":142},"EDUC 203":{"code":"EDUC 203","title":"Foundations of Reading","credits":"3","description":"This course explores the foundational knowledge needed to learn to read. It examines the psychological, sociocultural, and linguistic foundations of reading and writing. Students will become familiar with the reading/language arts standards in the Iowa Core Curriculum and with Iowa’s reading screening assessments. Additional components include the connection between oral vocabulary and learning to read; the stages of reading, writing, and spelling development; the alphabetic principal; and the “five pillars” of reading instruction: phonological awareness (specifically phonemic awareness), phonics, word analysis, fluency, and comprehension. Offered every fall.","offering":"Offered every fall.","sourcePage":142},"EDUC 204":{"code":"EDUC 204","title":"Curriculum, Instruction, and Assessment","credits":"3","description":"This course introduces preservice teachers to the core principles of effective teaching, including the relationship between curriculum, instruction, and assessment. Students will examine instructional frameworks such as Universal Design for Learning (UDL), explore evidence-based instructional strategies including high-leverage practices (HLPs), and scaffolding, and learn how to use formative, summative, and ongoing assessments to monitor learning. Emphasis is placed on how data informs instructional planning, differentiation, and decision- making to support all learners.","offering":"","sourcePage":142},"EDUC 205":{"code":"EDUC 205","title":"William Penn University Education Seminar","credits":"0","description":"This seminar is required for transfer students who have completed an introduction to education course at another institution. Lab fee required. Offered every fall and spring.","offering":"Offered every fall and spring.","sourcePage":142},"EDUC 218":{"code":"EDUC 218","title":"Elementary Physical Education and Health Methods","credits":"2","description":"This course is designed to acquaint elementary education majors with games and play activities appropriate for classroom use. Students will be informed of the components of fitness and how to encourage active lifestyles which meet the physical, social, and psychological needs of children. Basic health concepts to enhance personal, family and community health and wellness will be covered. Topics to be included are promoting and monitoring physical fitness, drug abuse education, classroom management, handicapping conditions, facilities and equipment, and integrating physical education and academics. National standards for elementary physical education will be discussed and examined. Offered every fall.","offering":"Offered every fall.","sourcePage":142},"EDUC 223":{"code":"EDUC 223","title":"Adolescent Literature for Teachers","credits":"3","description":"Students examine the characteristics of quality adolescent literature in each of the various genres. Student examine how adolescent literature reflects society and culture, including perspectives on gender roles and multicultural issues, how adolescent literature has changed over time, and the modern phenomenon of “banned” or “challenged” books. Students review strategies for teaching diverse learners and examine the use of text sets, choice books, technology links, trade books, audio books, author studies, performance assessments, and book-to- film features to incorporate across the curriculum. Students examine how to use quality young adult books in teaching, how to organize class libraries, and how to engage adolescents in reading activities. Offered through Distance Learning every summer and spring of odd years.","offering":"Offered through Distance Learning every summer and spring of odd years.","sourcePage":142},"EDUC 240":{"code":"EDUC 240","title":"Elementary Fine Arts Methods","credits":"2","description":"This course emphasizes the use of the fine arts in the regular elementary classroom. Students will explore ways to integrate fine arts (visual arts and music) into the elementary curriculum and how to use the arts to help students better comprehend core subjects defined by the Iowa Core. Fee required. Offered every fall.","offering":"Offered every fall.","sourcePage":143},"EDUC 250":{"code":"EDUC 250","title":"Language Acquisition","credits":"3","description":"This course introduces the theories and research of oral language development and emergent reading and writing skills. The course emphasizes strategies for supporting English Language Learners through oral language and vocabulary development. Offered every fall.","offering":"Offered every fall.","sourcePage":143},"EDUC 255":{"code":"EDUC 255","title":"Elementary Music Methods","credits":"3","description":"Students explore the principles and techniques of teaching elementary music; selecting materials, integration of music into elementary curriculum, and unit and lesson planning are integral parts of this course. Topics include, but will not be limited to, the use of Orff instruments, Kodaly methods, recorders, traditional styles and genres, and world music. Designed for the Music Education major, teaching strategies and assessment tools for Pre-K- 7th grade students will be studied. Offered every fall.","offering":"Offered every fall.","sourcePage":143},"EDUC 265":{"code":"EDUC 265","title":"Children’s Literature","credits":"3","description":"Students will understand that children’s literature (K-8) is both an artistic expression and an essential tool for literacy instruction. Students will analyze a wide variety of genres, formats, and cultural perspectives to support reading, writing, and critical thinking. Emphasis is placed on how literature shapes teaching practices by informing text selection, promoting responsive pedagogy, and connecting theory to meaningful classroom application. Offered spring semester/campus.","offering":"Offered spring semester/campus.","sourcePage":143},"EDUC 350":{"code":"EDUC 350","title":"Technology in the Classroom","credits":"2","description":"This course is designed to acquaint prospective teachers with the operation and appropriate use of a wide array of instructional media. Students will also gain background and skills in developing their online presence, including website creating, podcasting, video/tutorial creation, and professional communication. Every semester online. Prerequisites: EDUC 100","offering":"","sourcePage":143},"EDUC 355":{"code":"EDUC 355","title":"Classroom Management","credits":"3","description":"This course is designed to equip educators with the tools necessary to create and maintain a physically and emotionally safe environment in which all students can learn. Students will learn how to identify and implement a variety of behavioral, instructional and management strategies. Every spring. Prerequisites: EDUC 200, EDSP 100","offering":"","sourcePage":143},"EDUC 360":{"code":"EDUC 360","title":"Content Area Reading","credits":"3","description":"Content Area Reading provides literary strategies for teaching content reading across the curriculum. Students will examine types of text structures, as well as the dimensions of content area vocabulary and comprehension. Reading Recovery strategies will be explored. Students will demonstrate knowledge and the ability to implement content area instruction in reading and writing that effectively uses a variety of research-based strategies and practices. Every fall and spring. Co-requisites: EDUC 380/380FE or a Special Methods course with a field experience","offering":"","sourcePage":143},"EDUC 365":{"code":"EDUC 365","title":"Human Relations for Teachers","credits":"3","description":"This course provides prospective teachers with knowledge, skills and resources that will enable them to work effectively with the variety of students they will encounter in today’s multicultural society. Every fall. Prerequisite: Educ 200","offering":"","sourcePage":144},"EDUC 368":{"code":"EDUC 368","title":"Elementary Physical Education Methods","credits":"3","description":"The primary goal of this course is to prepare pre-service physical education students to effectively and efficiently teach Physical Education at the elementary level. Topics include: National standards, unit/lesson planning, classroom management and organization, assessment, social emotional learning and activity/game ideas. Students will gain valuable experience through field experience hours off-campus. Offered every spring. Prerequisite – Physical Education Majors of junior standing or admission from instructor","offering":"Offered every spring.","sourcePage":144},"EDUC 370":{"code":"EDUC 370","title":"Literacy Methods","credits":"3","description":"Students will learn and apply methods to teach the components of literacy. Students will learn how to implement scientifically based reading research to meet the unique needs of all learners. Students will understand how to utilize the MTSS framework to design and differentiate instructional groups. Students will become familiar with content area reading strategies, instructional technology, curricular materials, and assessments in reading. Every fall/campus Prerequisite: EDUC 203 Co-requisites: EDUC 370FE","offering":"","sourcePage":144},"EDUC 370FE":{"code":"EDUC 370FE","title":"Literacy Methods 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Literary Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-requisite: EDUC 370","offering":"","sourcePage":144},"EDUC 372":{"code":"EDUC 372","title":"Elementary Mathematics Methods","credits":"3","description":"Students review math topics taught in elementary schools, as well as explore a variety of ways to teach these concepts. Activities include working with manipulative, production of materials, unit and lesson planning, and sharing of instructional activities. This course is taught as part of a spring semester block and includes a 25-hour field experience. Every spring. Prerequisite: EDUC 200 Co-requisites: EDUC 372FE","offering":"","sourcePage":144},"EDUC 372FE":{"code":"EDUC 372FE","title":"Elementary Mathematics Methods 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Elementary Mathematics Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-requisite: EDUC 372","offering":"","sourcePage":145},"EDUC 374":{"code":"EDUC 374","title":"Elementary Language Arts Methods","credits":"3","description":"Students will learn and apply methods to teach language arts curriculum with an emphasis on writing instruction, including reading-writing connections, spelling, and the writing process as it applies to text types and purposes. Students will apply evidence-based strategies to meet the unique needs of all learners. Every spring/campus Prerequisite: EDUC 203","offering":"","sourcePage":145},"EDUC 375":{"code":"EDUC 375","title":"Reading Practicum","credits":"3","description":"This course reviews basic instruction in reading theory and methods; including causes, prevention and correction of reading difficulties. Students engage in a practicum experience where they will assess students’ reading abilities and provide appropriate remediation. Offered every fall, spring and summer Prerequisite: EDUC 370","offering":"","sourcePage":145},"EDUC 376":{"code":"EDUC 376","title":"Elementary Science Methods","credits":"3","description":"This course is designed to expose prospective teachers to a wide variety of elementary science resources, methods, and techniques. Activities include labs, research, unit and lesson planning, and activity presentations. Fee required. Every spring. Prerequisite: EDUC 200","offering":"","sourcePage":145},"EDUC 378":{"code":"EDUC 378","title":"Elementary Social Studies Methods","credits":"3","description":"Students explore a variety of resources and techniques that can be used to facilitate learning in the areas of elementary history, government, sociology, anthropology, economics, and geography. Activities include research, unit and lesson planning, and sharing of activities. Every fall. Prerequisite: EDUC 200","offering":"","sourcePage":145},"EDUC 380":{"code":"EDUC 380","title":"Secondary General Methods","credits":"3","description":"This course is designed to acquaint students with methods of teaching at the secondary level. Topics of study include learning styles, varied teaching strategies, lesson plan design, unit design, assessment strategies, and establishment of a productive classroom environment. Students complete a credit/no credit 25-hour field experience as part of the course requirements. Every spring. Prerequisites: EDUC 100:01 or 02, EDUC 200, Admission to Teacher Education Program","offering":"","sourcePage":145},"EDUC 380FE":{"code":"EDUC 380FE","title":"Secondary General Methods 25-Hour Field Experience","credits":"","description":"0 credit hours Students must enroll in this 25-hour field experience concurrently with General Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every spring. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 380","offering":"","sourcePage":145},"EDUC 382":{"code":"EDUC 382","title":"Secondary Business Methods","credits":"3","description":"Students learn how to apply the knowledge gained in General Secondary Methods to the teaching of secondary general business. Modern methods of teaching and a credit/no credit 25-hour field experience are integral components of this course. Every fall. Prerequisite: EDUC 380, Admission to Teacher Education Program Co-Requisite: EDUC 382FE","offering":"","sourcePage":146},"EDUC 382FE":{"code":"EDUC 382FE","title":"Secondary Business Methods 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Secondary Business Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 382","offering":"","sourcePage":146},"EDUC 384":{"code":"EDUC 384","title":"Secondary English Methods","credits":"3","description":"Students learn how to apply the knowledge gained in General Secondary Methods to the teaching of secondary English. Modern methods of teaching and a credit/no credit 25-hour field experience are integral components of this course. Every fall. Prerequisite: EDUC 380, Admission to Teacher Education Program Co-Requisite: EDUC 384FE","offering":"","sourcePage":146},"EDUC 384FE":{"code":"EDUC 384FE","title":"Secondary English Methods 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Secondary English Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 384","offering":"","sourcePage":146},"EDUC 386":{"code":"EDUC 386","title":"Secondary Industrial Technology Methods","credits":"3","description":"Students learn how to apply the knowledge gained in General Secondary Methods to the teaching of industrial technology. Modern methods of teaching and a credit/no credit 25-hour field experience are integral components of this course. Every fall. Prerequisite: EDUC 380, Admission to Teacher Education Program Co-Requisite: EDUC 386FE","offering":"","sourcePage":146},"EDUC 386FE":{"code":"EDUC 386FE","title":"Secondary Industrial Technology Methods 25-Hour Field Experience","credits":"","description":"0 credit hours Students must enroll in this 25-hour field experience concurrently with Secondary Industrial Technology Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 386","offering":"","sourcePage":146},"EDUC 388":{"code":"EDUC 388","title":"Secondary Math Methods","credits":"3","description":"Students learn how to apply the knowledge gained in General Secondary Methods to the teaching of secondary mathematics. Modern methods of teaching and a credit/no credit 25-hour field experience are integral components of this course. Every fall. Prerequisite: EDUC 380, Admission to Teacher Education Program Co-Requisite: EDUC 388FE","offering":"","sourcePage":147},"EDUC 388FE":{"code":"EDUC 388FE","title":"Secondary Math Methods 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Secondary Math Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 388","offering":"","sourcePage":147},"EDUC 391":{"code":"EDUC 391","title":"Secondary Physical Education Methods","credits":"3","description":"The primary goal of this course is to prepare pre-service physical education students to effectively and efficiently teach Physical Education at the secondary level. Topics include: National standards, unit/lesson planning, classroom management and organization, assessment, motor-behavior concepts, and activity/game ideas. Every fall. Prerequisite: EDUC 368 or professor approval Co-Requisite: EDUC 391FE","offering":"","sourcePage":147},"EDUC 391FE":{"code":"EDUC 391FE","title":"Secondary Physical Education 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Secondary Physical Education Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 391","offering":"","sourcePage":147},"EDUC 393":{"code":"EDUC 393","title":"Secondary Science Methods","credits":"3","description":"Students learn how to apply the knowledge gained in General Secondary Methods to the teaching of secondary science. Modern methods of teaching and a credit/no credit 25-hour field experience are integral components of this course. Every fall. Prerequisite: EDUC 380, Admission to Teacher Education Program Co-Requisite: EDUC 393FE","offering":"","sourcePage":147},"EDUC 393FE":{"code":"EDUC 393FE","title":"Secondary Science Methods 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Secondary Science Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 393","offering":"","sourcePage":148},"EDUC 395":{"code":"EDUC 395","title":"Secondary Social Studies Methods","credits":"3","description":"Students learn how to apply the knowledge gained in General Secondary Methods to the teaching of secondary social science. Modern methods of teaching and a credit/no credit 25-hour field experience are integral components of this course. Every fall. Prerequisite: EDUC 380, Admission to Teacher Education Program Co-Requisite: EDUC 395FE","offering":"","sourcePage":148},"EDUC 395FE":{"code":"EDUC 395FE","title":"Secondary Social Studies Methods 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Secondary Social Studies Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 395","offering":"","sourcePage":148},"EDUC 397":{"code":"EDUC 397","title":"(A, B, C) Secondary K-12 Music Methods in Teaching","credits":"","description":"3 credit hours (1 each in Instrumental, Choral and General Music Methods) Students learn how to apply the knowledge gained in General Secondary Methods of the teaching of secondary music in each of three areas: Instrumental, Choral & General Methods. Modern methods of teaching and a credit/no credit 25-hour field experience are integral components of this course. Students must enroll in all three (A, B and C) to get credit for the class. Offered fall semester. Prerequisite: EDUC 380, Admission to Teacher Education Program Co-Requisite: EDUC 397FE","offering":"Offered fall semester.","sourcePage":148},"EDUC 397FE":{"code":"EDUC 397FE","title":"(A, B, C) Secondary K-12 Music Methods 25-Hour Field Experience","credits":"0","description":"Students must enroll in this 25-hour field experience concurrently with Secondary K-12 Music Methods in Secondary Teaching. Grades will be assigned as credit/no credit, with no credit grades assigned to students who performed unsatisfactorily during the experience. Every fall. Prerequisites: Admission to the Teacher Education Program, Acceptable Dispositions Co-Requisite: EDUC 397 Per Iowa Law, changes have occurred to the Student Teaching requirements, allowing for some reduction in Student Teaching hours based on certain criteria. For explanation, see the Education Guidebook. All of the following Student Teaching options have Admission to Student Teaching as a Prerequisite:","offering":"","sourcePage":148},"EDUC 400":{"code":"EDUC 400","title":"16-Week Elementary Education Student Teaching","credits":"","description":"14 credit hours Students spend 16 weeks observing and student teaching in a K-6 classroom under the direction of a classroom teacher and university supervisor. During the semester, student teachers are required to attend professional development seminars. Fee of $300 required. Every fall and spring.","offering":"","sourcePage":148},"EDUC 401":{"code":"EDUC 401","title":"16-Week Secondary Education Student Teaching - Non-PE and Music Majors","credits":"14","description":"Students spend 16 weeks observing and student teaching in a 7-12 classroom under the direction of a classroom teacher and university supervisor. During the semester, student teachers are required to attend professional development seminars. Fee of $300 required. Every fall and spring.","offering":"","sourcePage":149},"EDUC 402":{"code":"EDUC 402","title":"16-Week K-12 Student Teaching - PE and Music Majors","credits":"14","description":"Physical Education/Health and Music majors spend 16 weeks observing and student teaching in elementary and secondary classrooms under the direction of classroom teachers and university supervisor. During the semester, student teachers are required to attend professional development seminars. Fee of $300 required. Every fall and spring.","offering":"","sourcePage":149},"EDUC 403":{"code":"EDUC 403","title":"02 2nd 8-Week Secondary Education Student Teaching - Non-PE and Music Majors","credits":"7","description":"Students spend 8 weeks observing and student teaching in 7-12 classroom under the direction of classroom teachers and a university supervisor. During the semester, student teachers are required to attend professional development seminars. Fee of $300 required. Every fall and spring.","offering":"","sourcePage":149},"EDUC 404":{"code":"EDUC 404","title":"02 2nd 8-Week Secondary Education Student Teaching - PE and Music Majors","credits":"7","description":"Students spend 8 weeks observing and student teaching in an elementary and secondary classroom under the direction of a classroom teacher and university supervisor. During the semester, student teachers are required to attend professional development seminars. Fee of $300 required. Every fall and spring.","offering":"","sourcePage":149},"EDUC 405":{"code":"EDUC 405","title":"02 2nd 8-Week Elementary Education Student Teaching","credits":"7","description":"Students spend 8 weeks observing and student teaching in a K-6 classroom under the direction of a classroom teacher and university supervisor. During the semester, student teachers are required to attend professional development seminars. Fee of $300 required. Every fall and spring. Note: Elementary or secondary student teachers seeking special education endorsement may complete both student teaching placements in the same semester, serving a split assignment of 8 weeks in the regular classroom and 8 weeks in the special education setting. A $450 student teaching fee is required. For all 8- week student teaching assignments, section 01 indicates 1st 8-weeks, and section 02 indicates 2nd 8-weeks.","offering":"","sourcePage":149},"ENGL 110":{"code":"ENGL 110","title":"Introduction to English Studies","credits":"","description":"3 credit hours Designed for first-year students to help plan and guide their undergraduate experience, this 8-week course familiarizes students with English studies while allowing students to understand how reading and writing skills are integral parts of their lives. The course strengthens the student’s writing and critical thinking skills by providing a close examination how to read and analyze a variety of texts, which will prepare them for future courses in the leadership core, English, and other disciplines. Offered every fall.","offering":"Offered every fall.","sourcePage":149},"ENGL 115":{"code":"ENGL 115","title":"Sports in Film and Literature","credits":"3","description":"An interdisciplinary course that introduces students to the world of sports as seen through the lenses of film and literature. We will examine how athletes and their sport are perceived in the culture at large by viewing films and reading fiction about different sports, including football, baseball, and soccer. We will view films and read selected short stories which highlight the many facets of an athlete’s life. We will also focus on how the plight of these athletes are influenced by their cultural settings and historical circumstances.","offering":"","sourcePage":150},"ENGL 131":{"code":"ENGL 131","title":"Intro to Creative Writing","credits":"2","description":"Designed to introduce students to poetry and short-fiction writing through reading model texts, writing poems ad workshopping student writing. The course also introduces students to methods regarding publishing their creative.","offering":"","sourcePage":150},"ENGL 200":{"code":"ENGL 200","title":"Theory of Language","credits":"3","description":"This is an introductory linguistics course. Students are introduced to modern grammar, including structural and transformation grammar, with some review of traditional grammar. A survey of the historical development of the English language is also included. Offered spring of odd years.","offering":"Offered spring of odd years.","sourcePage":150},"ENGL 215":{"code":"ENGL 215","title":"Business and Technical Communications","credits":"3","description":"Written communications stressing conciseness, clarity, precision, audience, revision, and persuasion. Memoranda, letters, reports, proposals, document design, graphic presentation, and other forms of workplace communications. Students will work in groups and will present their projects in formal presentations. Offered every fall. Prerequisite: LDRS 102","offering":"Offered every fall.","sourcePage":150},"ENGL 216":{"code":"ENGL 216","title":"Literary Genres","credits":"3","description":"An examination of one of the following genres: poetry, fiction, drama, film, or nonfiction literature. May be repeated as long as topics are not duplicated. Offered every fall. Literary Genres: Drama Same as THEA 216","offering":"Offered every fall.","sourcePage":150},"ENGL 219":{"code":"ENGL 219","title":"Media Literacy","credits":"3","description":"Designed to strengthen the student’s writing and critical thinking skills by providing a close examination of how the media constructs messages. Tailored to fit the student’s needs for a variety of future career paths, students will explore and compose in various genres such as social media, print journalism, advertisements, and documentary film. Offered spring of odd years.","offering":"Offered spring of odd years.","sourcePage":150},"ENGL 220":{"code":"ENGL 220","title":"Introduction to Literature","credits":"3","description":"Primer for upper-level literature courses, covering drama, fiction, poetry, and film. This course introduces the terminology of literature as well as the fundamentals of how to read, discuss, and write about a literary text. Offered every spring. Prerequisite: LDRS 101","offering":"Offered every spring.","sourcePage":151},"ENGL 223":{"code":"ENGL 223","title":"Adolescent Literature","credits":"3","description":"Selected literary and theoretical works are read, which highlight the universal coming-of-age dilemmas of adolescents. Offered every fall. Prerequisite: ENGL 220 or consent of instructor.","offering":"Offered every fall.","sourcePage":151},"ENGL 226":{"code":"ENGL 226","title":"British Literature To 1784","credits":"3","description":"A survey of British literature from the Middle-Ages to the Eighteenth Century, including Beowulf, Chaucer, Shakespeare, and Milton. Organized in historical sequence, attention will be paid to both historical interpretation and to the connection between the writer and contemporary reader. Offered fall of even years. Prerequisite: ENGL 220 or consent of instructor","offering":"Offered fall of even years.","sourcePage":151},"ENGL 227":{"code":"ENGL 227","title":"British Literature Since 1784","credits":"3","description":"A study of selected writings, beginning with Romantics such as Blake, Coleridge, Wordsworth, Shelley and Keats; extending through Victorian poetry and prose; and culminating with twentieth century moderns such as Yeats, Lawrence, Joyce, and Woolf. Offered spring of odd years. Prerequisite: ENGL 220 or consent of instructor","offering":"Offered spring of odd years.","sourcePage":151},"ENGL 231":{"code":"ENGL 231","title":"Creative Writing","credits":"3","description":"Dynamics of creative process in fiction, poetry, and drama. Exploration of student writing through interchange of ideas and reactions in weekly seminars. Offered every spring. Prerequisite: LDRS 102","offering":"Offered every spring.","sourcePage":151},"ENGL 237":{"code":"ENGL 237","title":"Multiethnic American Literature of the U.S.","credits":"3","description":"An interdisciplinary course that introduces students to the various voices that make up the evolving canon of ethnic American literature. We will examine a variety of theories to help us make sense of the various voices of modern American writing. We will view videos and documentaries and read selected essays and fictional stories that highlight the challenges and joys of various ethnic communities. Offered spring of odd years. Prerequisite: ENGL 220 Introduction to Literature","offering":"Offered spring of odd years.","sourcePage":151},"ENGL 238":{"code":"ENGL 238","title":"American Literature To 1865","credits":"","description":"3 credit hours Survey of early American authors from the Colonial, Enlightenment, and Romantic periods. Examines the emergence of an American literary identity from its Puritan origins to the Civil War. Offered fall of odd years. Prerequisite: ENGL 220 or consent of instructor","offering":"Offered fall of odd years.","sourcePage":151},"ENGL 239":{"code":"ENGL 239","title":"American Literature Since 1865","credits":"3","description":"A survey of American writing from the Civil War to the latter part of the Twentieth Century. Examines trends including Realism, Modernism, and Postmodernism; also covers emerging minority writers. Offered spring of even years. Prerequisite: ENGL 220 or consent of instructor","offering":"Offered spring of even years.","sourcePage":152},"ENGL 245":{"code":"ENGL 245","title":"Writing Consultation","credits":"3","description":"Students will learn techniques for tutoring individuals and groups, including strategies for critiquing others’ work, writing collaboratively, and giving presentations. Offered every fall. Prerequisite: LDRS 102 with grade of B or above","offering":"Offered every fall.","sourcePage":152},"ENGL 300":{"code":"ENGL 300","title":"Technical Editing","credits":"3","description":"By working with a diverse array of professional documents in various media from multiple industries, students will learn strategies for designing processes that respond to the unique demands of specific editing tasks. Offered fall of odd years.","offering":"Offered fall of odd years.","sourcePage":152},"ENGL 307":{"code":"ENGL 307","title":"Shakespeare","credits":"3","description":"An in-depth examination of Shakespeare’s plays and poetry. Opportunities include attending or participating in at least one Shakespeare performance or event. Offered spring of even years. Same as THEA 307 Prerequisite: ENGL 220 or consent of instructor","offering":"Offered spring of even years.","sourcePage":152},"ENGL 309":{"code":"ENGL 309","title":"Literary Theory","credits":"3","description":"Literary theory offers students the opportunity to learn to read from various perspectives. In this course students will gain knowledge of the history of literary theory as well as contemporary theories, such as Feminism, Ethical studies, Cultural studies, and others. Students will develop their ability to read, write, and think with greater critical acumen as they analyze and apply theories to literary texts. Offered fall of odd years. Prerequisite: ENGL 220","offering":"Offered fall of odd years.","sourcePage":152},"ENGL 310":{"code":"ENGL 310","title":"Advanced Writing","credits":"3","description":"Designed to build on the student’s writing skills and individually tailored to meet the student’s needs in personal development towards the chosen career field. Non-fiction writing, in-depth analysis of current issues, narrative essays, interviews, reviews, and creative writing may be used as course assignments. Offered every spring. Prerequisite: C or higher in LDRS 102","offering":"Offered every spring.","sourcePage":152},"ENGL 319":{"code":"ENGL 319","title":"Rhetoric and Technology","credits":"3","description":"Technology mediates all human activity including thought itself. As such, any technological change will affect how we see ourselves and the world around us, which affects how we communicate and persuade. In this course, students will use rhetorical theory to analyze specific contexts to understand how technology structures power and influences belief. From this understanding, students will be better prepared to make critical choices regarding the use of technology. Offered fall of odd years.","offering":"Offered fall of odd years.","sourcePage":153},"ENGL 330":{"code":"ENGL 330","title":"Information Design and Usability","credits":"3","description":"Students will learn how elements of design affect how people engage with print, multimedia, and web-based texts, and as such, how those design elements elicit or hinder a desired social action. From this understanding, students will learn how to develop protocols for conducting, analyzing, and making recommendations from usability testing. Offered spring of even years.","offering":"Offered spring of even years.","sourcePage":153},"ENGL 331":{"code":"ENGL 331","title":"Advanced Creative Writing, Poetry & Fiction","credits":"3","description":"Designed to build on the student’s writing skills and is individually tailored to meet the student’s needs in personal development towards poetry and fiction. Prerequisite: ENGL 231, Creative Writing","offering":"","sourcePage":153},"ENGL 345":{"code":"ENGL 345","title":"Grant & Proposal Writing","credits":"3","description":"This course will familiarize students with key genres of writing related to grants, such as letters of inquiry, applications, assessment documents, and reporting documents. In conversation with local professionals, students will learn rhetorical strategies for designing and composing these documents in response to specific community needs and in relation to stakeholder values. Offered fall of even years.","offering":"Offered fall of even years.","sourcePage":153},"ENGL 350":{"code":"ENGL 350","title":"Early World Literature","credits":"3","description":"English translations of literary masterpieces from ancient times through the early Eighteenth Century. Representative authors include Homer, Virgil, Dante, and Cervantes. Offered fall of even years. Prerequisite: ENGL 220 or consent of instructor","offering":"Offered fall of even years.","sourcePage":153},"ENGL 351":{"code":"ENGL 351","title":"Modern World Literature","credits":"3","description":"English translations of significant works of late eighteenth through twenty-first century authors such as Goethe, Dostoevsky, Kafka, Borges, and Camus. Offered spring of odd years. Prerequisite: ENGL 220 or consent of instructor","offering":"Offered spring of odd years.","sourcePage":153},"ENGL 360":{"code":"ENGL 360","title":"Advanced Argument","credits":"3","description":"Advanced Argumentation looks at argument as a means for problem solving. Students study argumentation theories as well as written and visual arguments in order to understand how argumentation can be used to improve communication, find common ground, and solve complex problems. Offered spring of odd years.","offering":"Offered spring of odd years.","sourcePage":153},"ENGL 370":{"code":"ENGL 370","title":"Sociolinguistics","credits":"3","description":"All social spaces are influenced by power structures. In this course students will develop a theoretical foundation for analyzing language patterns to identify the structures mediating specific social contexts and how those structures impact people’s lives. By the end of the course students will be better prepared to navigate institutional and organizational hierarchies; identify how social systems and structures can perpetuate harm; and propose grounded recommendations for systemic reform.","offering":"","sourcePage":154},"ENGL 390":{"code":"ENGL 390","title":"Special Topics in Technical Communication","credits":"3","description":"This course will focus on a topic that’s currently under debate in the field of technical communication. Through summarizing, synthesizing, and responding to scholarly arguments, students will develop their own stance on the special topic based on how it relates to their current and future professional endeavors. Some possible topics may include globalization and communication, communication in health care, plain language, universal design and accessibility, and copyright and fair use. Offered spring of even years.","offering":"Offered spring of even years.","sourcePage":154},"ENGL 460":{"code":"ENGL 460","title":"Capstone Project","credits":"3","description":"The Capstone Project is designed to be a culminating experience for English majors. Students will develop a project with a faculty mentor to connect their experience in the English major with their post-collegiate goals. This project could take many forms, but each student’s project will demonstrate the skills, theories, and rhetorical strategies they have learned in English studies. Offered every spring.","offering":"Offered every spring.","sourcePage":154},"ENGR 100":{"code":"ENGR 100","title":"Introduction to Engineering","credits":"1","description":"Introduces various aspects of engineering academics and professions ranging from academic coursework, careers, industries, opportunities, and expectations of engineers as professionals. The course also involves team work, communication skills, engineering ethics, creativity and engineering problem-solving activities involving hands-on projects. Offered every spring semester. Prerequisite: LDRS 100","offering":"Offered every spring semester.","sourcePage":154},"ENGR 101":{"code":"ENGR 101","title":"Engineering Graphics I","credits":"3","description":"Introduction to solid modeling with Autodesk Inventor. Students will utilize the software to create parts, fully dimensioned drawings, assemblies, and presentations. Students will produce a complete set of professional quality working drawings. Offered every fall.","offering":"Offered every fall.","sourcePage":154},"ENGR 102":{"code":"ENGR 102","title":"Engineering Graphics II","credits":"3","description":"Introduction to 2D drawing using AutoCAD. Will include orthographic projections, dimensioning, tolerancing, sections, auxiliaries, fasteners, and pictorials. Students will produce a complete set of professional quality working drawings. Offered every spring.","offering":"Offered every spring.","sourcePage":154},"ENGR 125":{"code":"ENGR 125","title":"Industrial Manufacturing Processes","credits":"3","description":"Industrial Manufacturing processing involving hand and machine operations. Planning, measurement, and precision layout. Lab fee required. Offered every fall.","offering":"Offered every fall.","sourcePage":155},"ENGR 215":{"code":"ENGR 215","title":"Materials and Processes","credits":"3","description":"Materials and processes used in manufacturing, including computer integration. Computer Numerical Control, robotics, automation, automatic factories, and material handling and storage. Lab fee required. Offered every spring.","offering":"Offered every spring.","sourcePage":155},"ENGR 260":{"code":"ENGR 260","title":"Introduction to Engineering Design","credits":"2","description":"Fundamentals of the engineering design process in various fields of engineering. Course will focus on design, research and analysis, teamwork, communication methods, engineering standards, and technical documentation. Course will also employ modem computer tools to aid in engineering design, analysis and problem solving. Offered every fall. Prerequisites: ENGR 100,101, APCS 201, MATH 241, PHYS 211","offering":"Offered every fall.","sourcePage":155},"ENGR 327":{"code":"ENGR 327","title":"Engineering Thermodynamics","credits":"3","description":"Introduction to the principles of work, energy and the physical properties of engineering fluids including temperature, pressure, internal energy, enthalpy, specific heat and entropy. The first and second laws of thermodynamics will be studied and used to analyze various thermodynamic processes common in engineering practice. The non-flow energy equation, continuity equation, Bernoulli’s equation and steady flow energy equation will be introduced. Calculations will also involve the ideal gas law, gases, and gas mixtures, steam and non-ideal gases. Offered every fall. Same as PHYS 327 Prerequisites: MATH 140/MATH 241 and PHYS 202/212","offering":"Offered every fall.","sourcePage":155},"ENGR 341":{"code":"ENGR 341","title":"Statics","credits":"3","description":"An introduction to the principles of engineering statics and the laws of equilibrium. Mathematical analysis of forces and moments acting on machine elements, frames and trusses at rest or in non-accelerated motion. The concepts of free body diagrams, inertia, friction and moment diagrams are introduced to help analyze multiple force systems. Classroom concepts will be applied to actual industrial problems to develop a method of problem evaluation and final solution. Offered every spring. Same as PHYS 341 Prerequisites: PHYS 201/211, MATH 241","offering":"Offered every spring.","sourcePage":155},"ENGR 342":{"code":"ENGR 342","title":"Dynamics and Kinematics","credits":"3","description":"An introduction to the principles of engineering dynamics, including particle position, displacement, velocity and acceleration. Newton’s laws will be used to evaluate the forces required to produce desired motions, velocities and accelerations of machine elements. Concepts of work, kinetic energy, impulse, momentum and the conservation of energy will be introduced and applied in the analysis of actual industrial problems. Offered every spring. Same as PHYS 342 Prerequisite: ENGR 341","offering":"Offered every spring.","sourcePage":155},"ENGR 343":{"code":"ENGR 343","title":"Mechanics of Materials","credits":"3","description":"An introduction to the concept of internal stresses in machine elements resulting from applied external force systems. Mathematical analysis of tension, compression, torsional and flexure stresses in machine elements and pressure vessels. Introduction and mathematical analysis of strain and deflections resulting from external forces. Classroom concepts will be applied to actual industrial problems to develop a method of problem evaluation and resolution. Offered every fall. Same as PHYS 343 Prerequisite: ENGR 341","offering":"Offered every fall.","sourcePage":156},"EXSC 205":{"code":"EXSC 205","title":"Theory and Practice of Strength Conditioning","credits":"3","description":"This course is designed to give students an understanding of how a collegiate strength and conditioning program operates, while also providing the opportunity to work directly with student-athletes. Offered fall and spring semesters.","offering":"Offered fall and spring semesters.","sourcePage":156},"EXSC 325":{"code":"EXSC 325","title":"Sport & Exercise Nutrition","credits":"3","description":"Influence of nutrients and energy metabolism on the individual’s health; adjustment of meal patterns to fulfill nutritional needs of the individual throughout the life cycle. Offered spring semester. Prerequisites: BIOL 216 or equivalent. Recommended: CHEM 101 & CHEM 102","offering":"Offered spring semester.","sourcePage":156},"EXSC 332":{"code":"EXSC 332","title":"Analysis of Human Motion","credits":"3","description":"Study of body movements, muscle action, and joint mechanics in relation to physical education activities; mechanical analysis of basic motor skills. Offered fall semester. Prerequisite: BIOL 216 or equivalent","offering":"Offered fall semester.","sourcePage":156},"EXSC 335":{"code":"EXSC 335","title":"Exercise Physiology","credits":"4","description":"An introduction to the study of how the human body responds to the demands of physical activity and how exercise affects the physiological functions of the body. Offered fall semester. Prerequisite: BIOL 216 or equivalent","offering":"Offered fall semester.","sourcePage":156},"EXSC 377":{"code":"EXSC 377","title":"Motor Development and Behavior","credits":"3","description":"This course acquaints students with motor development patterns across the lifespan (infancy through older adults). Additionally, students will be made aware of normal and abnormal development as well as have practical experience assessing motor development in pre and school age children as well as in older adults. Offered fall semester Prerequisite: PSYC 102 and EXSC 205","offering":"","sourcePage":156},"EXSC 390":{"code":"EXSC 390","title":"Exercise Science Practicum","credits":"","description":"1 credit, taken twice An Exercise Science capstone course in which students will integrate knowledge and skills learned in the progression of their education. Students will conduct research and produce a presentation-quality manuscript and/or poster for display at a local, regional, or national conference. Prerequisite: Senior standing Pre/Co-requisite: KINS 334 or MATH 220","offering":"","sourcePage":157},"EXSC 420":{"code":"EXSC 420","title":"Biomechanics","credits":"4","description":"Study of forces on the human body; application of Newtonian mechanics to problems of human motion. Topics covered include linear & angular kinematics & kinetics, motion in fluid medium. 3-hour lecture, 1-hour lab per week. Offered spring semester. Prerequisites: PHYS 201 & EXSC 332","offering":"Offered spring semester.","sourcePage":157},"EXSC 430":{"code":"EXSC 430","title":"Advanced Exercise Physiology","credits":"4","description":"Advanced study of exercise physiology topics, including adaptations to exercise training, environmental influences on performance, age & sex considerations in sports and exercise, and the impact of physical activity on disease states, including cardiovascular disease, diabetes, and obesity. 3-hour lecture, 1-hour lab per week. Offered spring semester. Prerequisite: EXSC 335","offering":"Offered spring semester.","sourcePage":157},"EXSC 437":{"code":"EXSC 437","title":"Exercise Prescription","credits":"3","description":"This course is designed to teach students how to test individuals and their fitness level, and then how to prescribe an exercise routine that will develop the individual to what they desire. Offered spring semester. Prerequisite: EXSC 332, KINS 334 & EXSC 335","offering":"Offered spring semester.","sourcePage":157},"EXSC 440":{"code":"EXSC 440","title":"Sports Pharmacology","credits":"3","description":"Pharmacologist principles including models of action, uses, modes of excretion, and patient side effects of various drug classes. The drugs are presented in a “system approach” with emphasis on medications utilized in diagnosing and treating diseases and injuries associated with the various body systems. 3 hours lecture per week; student oral presentations and case studies. Offered fall semesters. Prerequisites: CHEM 101 and CHEM 102","offering":"Offered fall semesters.","sourcePage":157},"GEOG 102":{"code":"GEOG 102","title":"Introduction to Geography","credits":"3","description":"This course introduces students to the basic concepts of geography. This course surveys the world’s major developed regions and their physical and human characteristics from a geographic perspective. This course is designed for students who are new to the field of geography.","offering":"","sourcePage":157},"GEOG 103":{"code":"GEOG 103","title":"Regional Geography of the Nonwestern World","credits":"3","description":"This course systematically surveys the peoples, cultures, resources, and problems of the cultural realms of the developing world (Latin America, Africa, the Islamic World, India, and China). Prerequisite: GEOG 102","offering":"","sourcePage":158},"HIST 130":{"code":"HIST 130","title":"American History to 1900","credits":"3","description":"Examines the political, economic, social, and cultural history of the United States from the Revolutionary War to 1900. Offered every fall.","offering":"Offered every fall.","sourcePage":158},"HIST 132":{"code":"HIST 132","title":"American History since 1900","credits":"3","description":"Examines the political, economic, social, and cultural history of the United States since 1900. Offered every spring.","offering":"Offered every spring.","sourcePage":158},"HIST 151":{"code":"HIST 151","title":"History of Western Civilization to 1648","credits":"3","description":"Examines the political, economic, social and cultural history of ancient civilizations with emphasis on China, Egypt, Greece, and Rome, the Middle Ages, the Renaissance, and the Reformation. Offered every fall.","offering":"Offered every fall.","sourcePage":158},"HIST 152":{"code":"HIST 152","title":"History of Western Civilization since 1648","credits":"3","description":"Examines the political, economic, social and cultural history of western civilizations since 1648, with emphasis on western civilization. Offered every spring.","offering":"Offered every spring.","sourcePage":158},"HIST 204":{"code":"HIST 204","title":"Christianity in America","credits":"3","description":"Examines the rise of both the Protestant and Catholic churches in America and the influence of Christianity upon American life and culture. Same as RELI 204","offering":"","sourcePage":158},"HIST 216":{"code":"HIST 216","title":"Perspectives in World History","credits":"3","description":"This course explores world history from multiple perspectives, to provide better understanding of contemporary America. Offered spring of odd years.","offering":"Offered spring of odd years.","sourcePage":158},"HIST 217":{"code":"HIST 217","title":"Perspectives in American History","credits":"3","description":"This course explores American history from multiple perspectives, to provide better understanding of contemporary America. Offered fall of even years.","offering":"Offered fall of even years.","sourcePage":158},"HIST 221":{"code":"HIST 221","title":"Women in American History","credits":"3","description":"Examines the political, economic, social, and cultural history of American women. Offered spring of even years. Same as PLSC 221/SOCI 221","offering":"Offered spring of even years.","sourcePage":159},"HIST 222":{"code":"HIST 222","title":"American Sports History","credits":"3","description":"Examines the history of baseball, football, and other team and individual sports, with emphasis on the twentieth century. Offered fall of odd years. Same as SMGT 222","offering":"Offered fall of odd years.","sourcePage":159},"HIST 230":{"code":"HIST 230","title":"Social Science for Elementary Education","credits":"3","description":"This course is designed to provide the Elementary Education student with a survey of social studies topics applicable to elementary teaching. Emphasis will be placed on history, geography, economics, political science and civic literacy. Offered spring semester.","offering":"Offered spring semester.","sourcePage":159},"HIST 234":{"code":"HIST 234","title":"African American History","credits":"3","description":"Examines the political, economic, social, and cultural history of African-Americans. Offered spring of odd years. Same as PLSC/SOCI 234","offering":"Offered spring of odd years.","sourcePage":159},"HIST 236":{"code":"HIST 236","title":"America in the Modern World","credits":"3","description":"Examines the diplomatic and military history of the United States since the Revolutionary War, with emphasis on the twentieth century. Offered spring of even years. Same as PLSC 236","offering":"Offered spring of even years.","sourcePage":159},"HIST 250":{"code":"HIST 250","title":"American Political Parties and Elections","credits":"3","description":"Examines the historical development, organization, functions, and tactics of American political parties and the historical development, method, style, and meaning of presidential and congressional election campaigns. Offered fall of even years. Same as PLSC 250","offering":"Offered fall of even years.","sourcePage":159},"HIST 251":{"code":"HIST 251","title":"Ancient History","credits":"3","description":"Examines the ancient Chinese, Egyptian, Mesopotamian, Asia Minor, Aegean, Greek and Hellenistic civilizations, the Roman Empire, and the rise of Christianity. Offered every fall of odd years.","offering":"Offered every fall of odd years.","sourcePage":159},"HIST 252":{"code":"HIST 252","title":"Medieval History","credits":"3","description":"Examines the medieval feudal system, society, church, governments, and culture, the conflicts between the medieval church and feudal states, the Islamic civilization, the commercial revival, the European exploration and colonization, the Renaissance, and the Reformation. Offered spring of even years.","offering":"Offered spring of even years.","sourcePage":159},"HIST 332":{"code":"HIST 332","title":"American Constitutional History","credits":"3","description":"Examines the historical development of the U. S. Supreme Court and its major decisions since the Federalist era. Offered fall of odd years. Same as PLSC 332","offering":"Offered fall of odd years.","sourcePage":160},"HIST 353":{"code":"HIST 353","title":"Civil War and Reconstruction","credits":"3","description":"Examines the causes, major political, diplomatic, and military events and results of the Civil War and political, economic, and social developments during Reconstruction. Offered fall of even years.","offering":"Offered fall of even years.","sourcePage":160},"HIST 354":{"code":"HIST 354","title":"Middle East History","credits":"3","description":"Examines the political, economic, social, and cultural history of the Middle East and North Africa from the rise of Islam to the present, with emphasis on civilizational change and relations with Western nations. Offered spring of odd years.","offering":"Offered spring of odd years.","sourcePage":160},"HIST 370":{"code":"HIST 370","title":"Second World War","credits":"3","description":"Examines the causes, major political, diplomatic, military events, and the results of the Second World War. Offered fall of even years.","offering":"Offered fall of even years.","sourcePage":160},"HIST 390":{"code":"HIST 390","title":"History/Government Practicum","credits":"3","description":"A capstone practicum which integrates knowledge gained through student’s major concentration and Penn Leadership Core courses. Offered every spring. Same as PLSC 390","offering":"Offered every spring.","sourcePage":160},"HRMC 453":{"code":"HRMC 453","title":"Employment Law","credits":"3","description":"This course provides an overview of balancing the needs of an organization with its working conditions and the legal rights of its employees. It also explores methods of dealing with collective bargaining and union relations, and it examines procedures for responding to grievances, complaints of discrimination, and wrongful discharge.","offering":"","sourcePage":160},"HRMC 454":{"code":"HRMC 454","title":"Strategic Management","credits":"3","description":"This course examines the functions and activities of human resources management in organizational structures. Students are exposed in processes used to develop policies as well as strategies for implementation. The topics of leadership, short- and long-range strategic planning, evaluation, benchmarking, change management, dealing with difficult people and conflict resolution are discussed. Students are also provided information about human resources management innovators and management philosophies.","offering":"","sourcePage":160},"HRMC 455":{"code":"HRMC 455","title":"Strategic Staffing","credits":"3","description":"The key components and processes of forecasting staffing needs, internal and external recruiting, hiring, orientation, and exit interviews are examined. Students are also exposed to labor laws and other governmental regulations related to employment.","offering":"","sourcePage":161},"HRMC 457":{"code":"HRMC 457","title":"Compensation and Benefits","credits":"3","description":"The methods and processes of analyzing, developing, implementing and administering pay structures and compensation and benefit packages are examined. The course explores performance-based pay, incentives, and related regulatory requirements. It also provides students with insights into creating balance between attractive compensation packages and overall organizational needs and goals.","offering":"","sourcePage":161},"HRMC 459":{"code":"HRMC 459","title":"Training and Development","credits":"3","description":"This course provides practical methods and tools for evaluating current and future organizational training needs. Methods for needs analysis, planning, development, and delivery and evaluation of training methods are examined. Strategies for building and maintaining a business environment supportive of ongoing learning and skill development are discussed, and the unique needs of particular employee groups are also addressed.","offering":"","sourcePage":161},"HS 390":{"code":"HS 390","title":"Human Services Practicum","credits":"3","description":"A capstone seminar course for Human Services majors. Students will be required to work a minimum of 100 hours field experience in an agency or organization providing individual and/or community human/social services. Further, students are expected to provide reflection on their field experience vis-a-vis the knowledge and skill sets gained through their program of study. Offered every spring.","offering":"Offered every spring.","sourcePage":161},"HUMA 357":{"code":"HUMA 357","title":"Internship","credits":"3","description":"Students will intern for employers to practice skills learned in their disciplines and to gain a deeper understanding of career expectations. Students must complete forty hours of work per academic credit. Students will also complete several assignments supervised by a WPU instructor. Prerequisite: Junior standing or instructor’s consent.","offering":"","sourcePage":161},"HUMA 390":{"code":"HUMA 390","title":"Applied Communication Seminar","credits":"3","description":"This is a capstone course for Humanities majors that focuses on career exploration, preparation, and obtainment. The course will help students discuss career preparation, placement, ethics, and development. Students will create a senior project that highlights their career readiness. Prerequisite: Senior standing or instructor’s consent.","offering":"","sourcePage":161},"INDU 107":{"code":"INDU 107","title":"Industrial Wood Processes","credits":"3","description":"Industrial wood processing involving hand tools and machine operations, lumber, fasteners, hardware, planning, processing, and finishing. Lab fee required. Offered every spring. Prerequisite: ENGR 125 recommended","offering":"Offered every spring.","sourcePage":162},"INDU 215":{"code":"INDU 215","title":"Materials & Processes","credits":"3","description":"Foundations for using technology responsibly. Materials and processes used in manufacturing, including computer integration and productivity. Discovering and developing creative design capabilities.","offering":"","sourcePage":162},"INDU 216":{"code":"INDU 216","title":"Automated Manufacturing Processes (CAM)","credits":"4","description":"Programming and operating Computer Numerical Controlled (CNC) equipment. Includes manual, conversational, and computer aided programming. Covers tool selection, speed and feed rates, fixturing considerations, setup sheets, and an introduction to robotics. Lab fee required. Offered spring of odd years. Prerequisites: ENGR 101, ENGR 125","offering":"Offered spring of odd years.","sourcePage":162},"INDU 218":{"code":"INDU 218","title":"Industrial Wood Processing","credits":"4","description":"Production of wood products involving hand and machine operations. Efficiency, production planning, inventory control, and costing. Lab fee required. Offered fall of even years. Prerequisite: INDU 107","offering":"Offered fall of even years.","sourcePage":162},"INDU 221":{"code":"INDU 221","title":"Applied Mechanical Engineering Technology","credits":"4","description":"Covers introductory theory of statics & strength of materials, mechanical power systems, fluid power systems, electrical power systems, and internal combustion engines. Half lecture, half lab. Lab stresses practical application of topics common to the field of mechanical engineering technology. Offered every spring. Prerequisite: MATH 120 or higher","offering":"Offered every spring.","sourcePage":162},"INDU 223":{"code":"INDU 223","title":"Welding Technology","credits":"4","description":"AC & DC flat position shielded metal arc welding (SMAW), GTAW, GMAW, and resistance welding, cutting, and flame spraying. Welding equipment, materials, supplies, and safety. Lab fee required. Offered spring of odd years. Prerequisite: ENGR 125","offering":"Offered spring of odd years.","sourcePage":162},"INDU 226":{"code":"INDU 226","title":"Industrial Metal Processing","credits":"4","description":"Production of metal products involving hand and machine operations utilizing sheet, cast, and machined metals. Precision layout and measurement stressed. Efficiency, production planning, inventory control, and costing. Lab fee required. Offered spring of even years. Prerequisite: ENGR 125","offering":"Offered spring of even years.","sourcePage":163},"INDU 227":{"code":"INDU 227","title":"Electrical Energy and Circuits","credits":"4","description":"Scientific theory of magnetism and electricity. An introduction to the generation and distribution of electrical energy. Application of Ohm’s Law and Watt’s Law to DC & AC circuits containing resistors, and/or capacitors, and/or inductors in series, parallel, and series/parallel combinations. Laboratory includes use of test equipment, breadboarding and troubleshooting of basic DC & AC circuits, and an introduction to residential wiring. Also includes units on Programmable Logic Controllers, basic electronics, and the construction of an individual project. Lab fee required. Offered every fall. Same as PHYS 227 Prerequisite: MATH 102 or MATH 120","offering":"Offered every fall.","sourcePage":163},"INDU 290":{"code":"INDU 290","title":"Building Construction","credits":"4","description":"Site layout, surveying, excavating, pouring and finishing concrete footings, foundations, and slabs, block and brick laying. Carpentry framing and finishing, insulating, drywalling, painting, and roofing. Construction procedures, tools and equipment, scheduling, cost estimating, and contract bidding. Lab fee required. Offered fall of odd years. Prerequisites: ENGR 101, INDU 107","offering":"Offered fall of odd years.","sourcePage":163},"INDU 315":{"code":"INDU 315","title":"Industrial Plastics","credits":"3","description":"Industrial processing of plastics; design, tooling, equipment, and processes. Lab fee required. Offered fall of odd years. Prerequisite: ENGR 125","offering":"Offered fall of odd years.","sourcePage":163},"INDU 324":{"code":"INDU 324","title":"Architectural Plans and Specifications","credits":"4","description":"Original design for a residence structure. Complete set of presentation drawings and documents, floor plans, elevations, plot plans, perspectives, specifications, cost estimates, construction time line, and a 3D model. Analysis and interpretation of architectural contract documents for construction details, structural and mechanical systems, and compliance with building codes. Lab fee required. Offered fall of odd years. Prerequisite: ENGR 102","offering":"Offered fall of odd years.","sourcePage":163},"INDU 329":{"code":"INDU 329","title":"Advanced Solid Modeling","credits":"3","description":"Solid modeling with Autodesk Inventor used to create advanced sweeps, blends, patterns, family tables, rounds, drafts, animations, and assemblies. Includes an original group design project. Desktop publishing software is used to import Creo graphics to develop a marketing brochure. Offered fall of even years. Previously called Graphics. Prerequisites: ENGR 101, LDRS 105","offering":"Offered fall of even years.","sourcePage":164},"INDU 333":{"code":"INDU 333","title":"Industrial Electronics","credits":"4","description":"Scientific theory of semiconductors. An introduction to circuits using diodes, transistors, and op-amps. Exploration of the use of transducers to interface mechanical, fluid, electrical, and thermal systems with emphasis placed on industrial automation and control. Laboratory activities include breadboarding and troubleshooting basic circuits, use of Programmable Logic Controllers, and various forms of electric motor controls. Construction of individual and group projects including original design of a printed circuit board is encouraged. Lab fee required. Offered spring of even years. Same as PHYS 333 Prerequisites: INDU 227 or PHYS 202/212","offering":"Offered spring of even years.","sourcePage":164},"INDU 346":{"code":"INDU 346","title":"Alternate Energy","credits":"3","description":"Exploration of alternatives (solar, wind, nuclear, geothermal, ocean thermal, biomass, conservation, and others) to presently used nonrenewable energy sources. Includes numerous field trips as well as the design and construction of a group alternate energy project. Emphasis placed on the analysis of the consequences associated with various energy paths. Lab fee required. Offered spring of odd years.","offering":"Offered spring of odd years.","sourcePage":164},"INDU 350":{"code":"INDU 350","title":"Manufacturing and Entrepreneurialism","credits":"3","description":"Operating a manufacturing enterprise; organization, methods, production planning and control, purchasing, quality control, sales, personnel, costs, and financing. Development of a consumer product from initial concept through marketing distribution. Lab fee required. Offered fall of even years. Prerequisites: ENGR 101, ENGR 125","offering":"Offered fall of even years.","sourcePage":164},"INDU 357":{"code":"INDU 357","title":"Internship","credits":"3-6","description":"Required of all Industrial Technology majors except Teacher Education and 3 + 2 Engineering unless replaced by INDU 390. Normally completed in the summer prior to the senior year but may be completed during the regular semesters of the senior year. Students put in a minimum of 60 hours of “on the job” work for each credit earned. Typical employment is in the areas of management, production, design, engineering support, and construction. All placements must be approved by the department before employment is started. All internships are paid positions. Also requires reading a current book in your field of interest and writing a capstone paper. INDU 390 Professional Development Seminar may be taken as a substitute for the internship requirement. Offered every fall, spring, and summer. Prerequisite: Senior standing","offering":"Offered every fall, spring, and summer.","sourcePage":164},"INDU 390":{"code":"INDU 390","title":"Professional Development Seminar","credits":"2","description":"Readings and discussion of professional and ethical issues; preparation of an individual’s professional portfolio. Participation in a professional meeting and presentation of a paper based on original research and/or ideas encountered at the meeting. Offered spring semester. May substitute for INDU 357. Same as APCS/MATH/PHYS 390 Prerequisite: Junior standing in INDU or consent of instructor Course descriptions for Engineering Graphics I & II, Industrial Metal Processing, Materials and Processes, Engineering Thermodynamics, Statics, Dynamics and Kinematics, and Mechanics of Materials are found under ENGR.","offering":"Offered spring semester.","sourcePage":165},"INSR 101":{"code":"INSR 101","title":"Foundations of Risk Management and Insurance","credits":"3","description":"This course provides an introduction to risk management concepts including risk assessment, risk control, risk financing, and specifically insurance as a risk management technique. Students will analyze the insurance policy and review common policy concepts as well as gain an understanding of big data analysis.","offering":"","sourcePage":165},"INSR 102":{"code":"INSR 102","title":"Insurance Company and Agency Operations","credits":"3","description":"The course provides an overview of how property-casualty insurance functions work together to create and deliver products. The course describes the various functions of an insurance company, including the marketing and distribution function, the underwriting function, and the claims function. In addition, insurance regulation, reinsurance, risk control, premium auditing, and strategic management is covered.","offering":"","sourcePage":165},"INSR 203":{"code":"INSR 203","title":"Personal Insurance","credits":"3","description":"This course provides students the opportunity to understand risk management techniques, and how they apply to personal insurance coverages. Topics covered in-depth include: personal insurance overview; automobile insurance and society; personal auto policy coverage and endorsements; homeowner’s policy coverage and endorsements; other common personal lines policies; and life insurance, retirement, and disability and health insurance planning. Prerequisites: INSR 101 recommended","offering":"","sourcePage":165},"INSR 204":{"code":"INSR 204","title":"Commercial Insurance","credits":"3","description":"This course provides students the opportunity to understand risk management techniques, and how they apply to commercial insurance coverages. Topics covered in-depth include: Commercial property insurance, business income insurance, commercial crime and equipment breakdown insurance, inland and ocean marine insurance, commercial general liability insurance, commercial auto insurance, worker’s compensation and employer’s liability insurance, business owners and farm insurance, and specialty coverages. Prerequisites: INSR 101 recommended","offering":"","sourcePage":165},"INSR 205":{"code":"INSR 205","title":"Delivering Insurance Services","credits":"3","description":"This course provides students the foundation of knowledge needed to learn improvement principles which will attract and retain clients. Topics covered include: The nature of the insurance business; customer identification, needs, wants, and the customer’s voice; key processes, the process improvement model, and process improvement tools; leadership, teamwork, and organizational structures; and assessment of progress. Prerequisites: INSR 101 recommended","offering":"","sourcePage":166},"INTR 102":{"code":"INTR 102","title":"Interdisciplinary Studies Introduction Seminar","credits":"1","description":"Overall explanation of what the major is and individual goals and specific plans for the students are formulated. This individual plan will be the guideline for completion of the major and used for evaluation and assessment. Offered in fall and spring Semesters.","offering":"Offered in fall and spring Semesters.","sourcePage":166},"INTR 103":{"code":"INTR 103","title":"Interdisciplinary Studies Career Development","credits":"1","description":"Directed study on career and major opportunities utilizing classroom and individual student analysis. Offered in fall and Spring Semesters.","offering":"Offered in fall and Spring Semesters.","sourcePage":166},"INTR 390":{"code":"INTR 390","title":"Interdisciplinary Studies Capstone","credits":"3","description":"Evaluation of the student’s experiences of the major and how they are going to use it in the future are enumerated. It consists of a capstone paper, presentation to the class, and discussion of how the major can be changed to better meet the needs of both the students and university. Offered every Spring Semester.","offering":"Offered every Spring Semester.","sourcePage":166},"KINS 110":{"code":"KINS 110","title":"Wellness and Fitness","credits":"3","description":"This course is designed to improve movement efficiency and provide knowledge of recreational activities. Included will be the effects of exercise on the body, basic nutrition, an introduction to relaxation and stress management techniques, and basic weight training principles. Offered fall & spring semesters.","offering":"Offered fall & spring semesters.","sourcePage":166},"KINS 150":{"code":"KINS 150","title":"Introduction to Kinesiology","credits":"3","description":"This course is designed to provide students with history, principles, career opportunities, and job requirements in the fields of sport, health and human performance. Offered fall & spring semesters.","offering":"Offered fall & spring semesters.","sourcePage":166},"KINS 160":{"code":"KINS 160","title":"First Aid and CPR/AED","credits":"1","description":"This course is designed to provide the opportunity for students to learn current methods and concepts in administering First Aid and CPR to accident victims. American Heart Association certification may be obtained for Adult, Child & Infant CPR, and Adult, Child & infant AED. Students will demonstrate knowledge, both written and applied, in the concepts described above. This course is not available to be taken via remote learning. Lab fee required. Offered as needed.","offering":"Offered as needed.","sourcePage":167},"KINS 208":{"code":"KINS 208","title":"Leadership in Sport, Exercise, & Recreation","credits":"3","description":"Leadership theories and techniques for professionals working in the field of sport, exercise, and recreation. The course will equip students with the knowledge, skills, and abilities to enhance the performance of others, including students, athletes, clients, and consumers. Offered fall and spring semesters.","offering":"Offered fall and spring semesters.","sourcePage":167},"KINS 210":{"code":"KINS 210","title":"Camp Management and Outdoor Education","credits":"3","description":"Preparation for duties of camp counselors and camp leadership positions; practical experience built around camp craft skills for outdoor living.","offering":"","sourcePage":167},"KINS 215":{"code":"KINS 215","title":"Elementary Physical Education Methods","credits":"3","description":"The primary goal of this course is to prepare students to effectively and efficiently teach Physical Education at the elementary level. Topics include: National standards, unit/lesson planning, classroom management, assessment, and activity/game ideas. Students will gain valuable experience through observation hours off- campus. Offered spring semester.","offering":"Offered spring semester.","sourcePage":167},"KINS 217":{"code":"KINS 217","title":"Adapted Physical Education","credits":"3","description":"This course is designed to expose students to unique needs addressed in IDEA as they relate to physical education. Accommodations for assessment, activities and other elements necessary to successful inclusion ae addressed. Offered spring semester.","offering":"Offered spring semester.","sourcePage":167},"KINS 218":{"code":"KINS 218","title":"Prevention and Care of Sports Injuries","credits":"3","description":"Theory and practical application involving prevention, care and rehabilitation of athletic injuries. Required of all students seeking a coaching certification. Lab fee required. Prerequisite: BIOL 216","offering":"","sourcePage":167},"KINS 221":{"code":"KINS 221","title":"Teaching Individual and Team Sports","credits":"3","description":"Theory and practice of the fundamentals, methods, and materials of teaching individual and team sports. Offered fall and spring semesters. Lab fee required.","offering":"Offered fall and spring semesters.","sourcePage":167},"KINS 227":{"code":"KINS 227","title":"Community Health","credits":"3","description":"Hygiene of the basic systems of the body with emphasis on care, functions and disorders, natural and acquired defenses against disease, elements of preventive medicine, and modern standards of sanitation. Exploration of causative community factors; diagnosis of disease and programs to combat these conditions. Offered spring semester.","offering":"Offered spring semester.","sourcePage":168},"KINS 231":{"code":"KINS 231","title":"Substance Abuse","credits":"3","description":"Study of alcohol and drug use with relevance to medical, psychological, sociological and legal dimensions in the United States with an emphasis on automobile-related issues.","offering":"","sourcePage":168},"KINS 295":{"code":"KINS 295","title":"Seminar in Kinesiology","credits":"2","description":"Instructor-guided discussion of current and emerging topics in sport management, recreation, and exercise science. Topics of interest may vary each time the course is offered. May be repeated once for credit.","offering":"","sourcePage":168},"KINS 318":{"code":"KINS 318","title":"Sports Injury Management Skills","credits":"3","description":"The student is introduced to the various methods and techniques used in injury assessment, taping and bandaging, therapeutic modalities and rehabilitation exercises. The focus of this course is directed toward skills necessary for managing a variety of situations that commonly occur in the field of athletic training and sports medicine. Recognizing and evaluating sports injuries is a necessary part of the responsibility of the person(s) working in the sports areas, along with knowing the hands- on techniques associated with injury care. Prerequisite: KINS 218","offering":"","sourcePage":168},"KINS 334":{"code":"KINS 334","title":"Tests and Measurements in Kinesiology","credits":"3","description":"Various testing techniques and statistical analysis of tests available for use in the field of Physical Education. Offered fall and spring semester. Prerequisite: MATH 102 or higher","offering":"Offered fall and spring semester.","sourcePage":168},"KINS 336":{"code":"KINS 336","title":"Organization and Administration of Physical Education","credits":"3","description":"This course is designed to provide students with knowledge, skills and abilities to effectively manage physical education and athletic programs. Areas of focus include K-12 public and private schools, as well as K-12 public and private recreational facilities. Offered fall and spring semester. Prerequisite: Junior standing","offering":"Offered fall and spring semester.","sourcePage":168},"KINS 338":{"code":"KINS 338","title":"Organization of School Health Program","credits":"3","description":"Organization and development of school health programs, dealing with hygiene, sanitation of the school plant, the lunch program, school health services and the health instructional program. Prerequisite: KINS 227 KINS/BIOL 356 Pre-Internship 1 credit hour This course will prepare students for an internship in a subsequent semester. Topics/activities include: Employer expectations, workplace etiquette, workplace attire, workplace behavior, resume and cover letter writing, mock- interviews. Culmination of course is an interview with a prospective employer with the aim of securing an internship position. Failure to obtain an internship position will preclude registration for KINS 357.","offering":"","sourcePage":168},"KINS 357":{"code":"KINS 357","title":"Internship","credits":"1-6","description":"Extensive work experience in an area related to student’s major field of concentration under the direct supervision of a regular faculty member and an on-site work supervisor. Approval of the faculty member, work supervisor, and division chair must be secured in advance of registration. This course may be taken more than once, for up to a total of 6 hours maximum credit per declared major. University guidelines specify a student must perform a minimum of 40 hours of meaningful work per credit hour earned. The division chair will oversee all internships credits. Prerequisite for: BIOL/KINS 356","offering":"","sourcePage":169},"KINS 377":{"code":"KINS 377","title":"Recreational Program Planning","credits":"3","description":"Recreation program planning is an essential part of health promotion and wellness and recreation. This course will lead students through the process of building a recreation program from the idea to the implementation. The course center around a semester-long project where students must plan, budget, implement, evaluate and maintain a recreation/health promotion program. Offered fall.","offering":"Offered fall.","sourcePage":169},"KINS 390":{"code":"KINS 390","title":"Kinesiology Practicum","credits":"2","description":"A Kinesiology capstone course in which students will integrate knowledge and skills learned in the progression of their education. Students will conduct research and produce a presentation-quality manuscript and/or poster for display at a local, regional, or national conference. Prerequisite: Senior standing Pre/Co-requisite: KINS 334 or MATH 220","offering":"","sourcePage":169},"LDRS 090":{"code":"LDRS 090","title":"Successful Writing","credits":"3","description":"This course will prepare students to successfully complete William Penn University’s Writing-Course sequence. Students in LDRS 090 will focus on the rudiments of writing and reading. The course will require students to complete short writing assignments to workshop their writing with peer groups, and to meet and discuss their writing with the instructor. The course will emphasize reading comprehension through discussion and short analysis assignments. Course credit does not count towards graduation. A “C-” or higher is required to take LDRS 101.","offering":"","sourcePage":169},"LDRS 100":{"code":"LDRS 100","title":"College Foundations","credits":"2","description":"College Foundations introduces the personal and leadership development emphasis of William Penn University, integrates students into the campus community, and assists them in adjusting to the academic environment of the university. College Foundations will 1) address skills essential to success as a life-long learner; 2) explore vital university resources such as the library, computer lab, and career services; 3) introduce the institution’s foundational values including the influence of its Quaker heritage; 4) encourage leadership and active involvement in service opportunities, extracurricular activities and student organizations. Required of all students with fewer than 12 hours of college credit, excluding dual credit.","offering":"","sourcePage":170},"LDRS 101":{"code":"LDRS 101","title":"English Composition I","credits":"3","description":"This course has been designed as an introduction to the writing process. Emphasis will be placed on pre- writing, careful drafting, and critical revision of the basic essay, with attention to audience analysis, identification of purpose, thesis formation, incorporation of supporting materials, and overall essay organization. Analysis of the students’ own writing and that of others will be emphasized. Offered every fall and spring. A “C-” or above is required to take LDRS 102. Prerequisite: LDRS 090 with grade of C- or above.","offering":"Offered every fall and spring.","sourcePage":170},"LDRS 102":{"code":"LDRS 102","title":"English Composition II","credits":"3","description":"Following English Composition I, this course continues developing students’ writing skills and prepares students for the research projects and critical thinking that they will need in future courses and beyond. Students will read scholarly writing, participate in discussion, study argument and research methods, and prepare research projects, such as a hypothesis, a project proposal or abstract, and an annotated bibliography. Offered every fall and spring. Prerequisite: LDRS 101 with grade of “C-” or above.","offering":"Offered every fall and spring.","sourcePage":170},"LDRS 103":{"code":"LDRS 103","title":"Educational Success","credits":"","description":"(replaces LDRS 100 for Distance Learning students) 3 credit hours Educational Success introduces the personal and leadership development emphasis of William Penn University, integrates students into the campus community, and assists them in adjusting to the academic environment of the university. Cooperative learning is the foundational methodology of the course. Educational Success will 1) address skills essential to success as a life-long learner; 2) explore vital university resources such as the library, computer lab, and career services; 3) introduce the institution’s foundational values including the influence of its Quaker heritage; 4) encourage leadership and active involvement in service opportunities, extracurricular activities and student organizations; 5) initiate the compilation of a personal leadership portfolio. Required of all students with less than 12 hours of college credit.","offering":"","sourcePage":170},"LDRS 105":{"code":"LDRS 105","title":"Computers and Technology","credits":"3","description":"Fundamental computer concepts, terminology, and skills applicable for communication in today’s world; awareness of critical issues in computer usage, including historical perspective, ethical practice, and current use of technology in various fields. Laboratory applications such as word processing, spreadsheet, database, programming, graphics, electronic mail, and Internet search tools will be part of individual and group projects. Lab fee required. Prerequisite: Math ACT>19, Math Assessment Exam placement, or consent of instructor.","offering":"","sourcePage":170},"LDRS 110":{"code":"LDRS 110","title":"Foundations and Quaker Values","credits":"3","description":"College Foundations and Quaker Values introduces the personal and leadership development of William Penn University, integrates students into the campus community, and assists them in adjusting to the academic environment of the university. College Foundations and Quaker Values will 1) address skills essential to success as a life-long learner; 2) explore vital university resources such as the library and career services; and, 3) introduce the institution’s foundational values including the influence of its Quaker heritage. With these values and beliefs as a foundation, this course will emphasize an understanding of the self and what we value, an awareness of the world and our responsibilities in it, and an understanding of ethical decision-making which transfers values into actions. Prerequisite: Online program","offering":"","sourcePage":171},"LDRS 200":{"code":"LDRS 200","title":"Principles of Communication","credits":"3","description":"Two foundational assumptions of this course are that communication skills are essential for successful social and vocational life and that communication competence is the mark of effective leadership. In this course basic communication principles related to intrapersonal, interpersonal, small group, and public speaking contexts will be introduced and discussed in theory and in practice. Offered every fall and spring. Prerequisite: LDRS 101 with grade of C- or above. Required for education certification.","offering":"Offered every fall and spring.","sourcePage":171},"LDRS 220":{"code":"LDRS 220","title":"Arts and Society I","credits":"3","description":"Focusing on art, music, theatre, literature and their impact on society, this course will equip the student with an understanding of early major movements and style periods in both the visual and performing arts and an appreciation for the works of major artists who were influential in changing society. The course will use lecture- demonstration, guided listening, small group discussion, attendance at cultural events, and field trips to museums and/or concerts to engage the student with the arts at a personal level. Content will cover the time periods of the early Egyptians to the Renaissance. Lab fee required. Offered every fall. Prerequisite: LDRS 102 with grade of C- or above.","offering":"Offered every fall.","sourcePage":171},"LDRS 221":{"code":"LDRS 221","title":"Arts and Society II","credits":"3","description":"Focusing on art, music, theatre, literature and their impact on society, this course will equip the student with an understanding of modern major movements and style periods in both the visual and performing arts and an appreciation for the works of major artists who were influential in changing society. The course will use lecture- demonstration, guided listening, small group discussion, attendance at cultural events, and field trips to museums and /or concerts to engage the student with the arts at a personal level. Content will cover the period of the Baroque through present day. Note that LDRS 220 is not a prerequisite. Lab fee required. Offered every spring. Prerequisite: LDRS 102 with grade of C- or above.","offering":"Offered every spring.","sourcePage":171},"LDRS 290":{"code":"LDRS 290","title":"Quaker Values","credits":"1","description":"A study of the beliefs and heritage of the early Society of Friends that are the heritage of this institution. With these values and beliefs as a foundation, this interdisciplinary course will emphasize an understanding of the self and what we value, an awareness of the world and our responsibilities in it, and an understanding of ethical decision-making which transfers values into actions. Offered every semester.","offering":"Offered every semester.","sourcePage":171},"LDRS 390":{"code":"LDRS 390","title":"Contemporary Leadership","credits":"3","description":"Principles and theories of effective leadership. The concept of leadership is analyzed, including definitions, characteristics, and skills of effective leadership. Observation, analysis, and evaluation of leadership as displayed by contemporary and historical people. The course also addresses the development of self- awareness of potential strengths and weaknesses of the students as leaders. Offered every semester. Prerequisite: Must have completed 75 credit hours","offering":"Offered every semester.","sourcePage":172},"MATH 095":{"code":"MATH 095","title":"Quantitative Literacy","credits":"2","description":"Extra support to facilitate success in target math course. Just-in-time learning of prerequisite math skills, assistance on topics from target course, and strategies to excel in mathematics. Co-requisite: MATH 105 or 210.","offering":"","sourcePage":172},"MATH 096":{"code":"MATH 096","title":"Algebraic Insights","credits":"2","description":"Extra support to facilitate success in target math course. Just-in-time learning of prerequisite math skills, assistance on topics from target course, and strategies to excel in mathematics. Co-requisite: MATH 102 or 120.","offering":"","sourcePage":172},"MATH 102":{"code":"MATH 102","title":"Intermediate Algebra","credits":"3","description":"Absolute value equations and inequalities, linear equations and inequalities, systems of equations, quotients of polynomials, synthetic division, rational expressions, radicals, complex numbers, quadratic equations and inequalities, and word problem applications. Offered every fall and spring. Does not fulfill core math requirement. Co-Requisite: MATH 096 (if necessary)","offering":"Offered every fall and spring.","sourcePage":172},"MATH 105":{"code":"MATH 105","title":"Mathematics for Leaders","credits":"3","description":"A survey of applied topics in mathematics including voting theory, finance, mathematical patterns, geometric similarity, probability, and statistics. Offered every semester. Co-requisite: MATH 095 (if necessary)","offering":"Offered every semester.","sourcePage":172},"MATH 120":{"code":"MATH 120","title":"Applied Mathematical Reasoning","credits":"3","description":"Prepares students to work with the necessary mathematical skills to succeed in their science or industrial courses. Course includes but is not limited to the following topics: Algebraic skills, Probability, Statistics, Right Triangle Trigonometry, Geometry, and Vectors. Student who need to take a physics course should not take this course. Co-Requisite: Math 096 (if necessary)","offering":"","sourcePage":172},"MATH 140":{"code":"MATH 140","title":"Pre-Calculus","credits":"4","description":"Composite and inverse functions, circles, parabolas, exponential/logarithmic functions and equations, trigonometric functions (graphs, inverses), trigonometric identities and equations, law of sines and cosines. Offered every fall and spring. Prerequisite: MATH 102 or equivalent, or a satisfactory score on the Mathematics Assessment Exam, or consent of the instructor.","offering":"Offered every fall and spring.","sourcePage":173},"MATH 205":{"code":"MATH 205","title":"Mathematics for Elementary Educators I","credits":"3","description":"A study of mathematical concepts related to topics taught in elementary schools. Topics include numbers and base-ten, fractions, addition, subtraction, multiplication, division, percentages, decimals, negative values, and algebra.","offering":"","sourcePage":173},"MATH 206":{"code":"MATH 206","title":"Mathematics for Elementary Educators II","credits":"3","description":"A study of mathematical concepts related to topics taught in elementary schools. Topics include geometry, measurement, algebraic concepts, data analysis, and probability. Prerequisite: MATH 205 with a grade of C- or better, or consent of instructor.","offering":"","sourcePage":173},"MATH 210":{"code":"MATH 210","title":"Financial Mathematics","credits":"3","description":"A survey course of common mathematical ideas from the business field including percentages, interest, loans, annuities, inflation, markup and markdown, basic statistical ideas, and basic probability. Co-requisite: MATH 095 (as needed) Prerequisite: BUSI 130 or consent of instructor","offering":"","sourcePage":173},"MATH 211":{"code":"MATH 211","title":"Discrete Mathematics","credits":"3","description":"Finite math for computer science majors stressing an algorithmic approach. Topics include Boolean algebra, number base conversions, binary arithmetic, matrices and determinants, graph theory, functions, and recursion. Offered every fall. Prerequisite: MATH 140 or equivalent","offering":"Offered every fall.","sourcePage":173},"MATH 212":{"code":"MATH 212","title":"Introduction to Abstract Mathematics","credits":"3","description":"Elementary logic, set theory, inductive and deductive reasoning, methods of proof, relations and orders, countable and uncountable sets. The course will emphasize the basic techniques of reading and writing proofs. Offered every spring. Prerequisite: MATH 211","offering":"Offered every spring.","sourcePage":173},"MATH 220":{"code":"MATH 220","title":"and MATH 336. Offered every semester. (Was MATH 303)","credits":"","description":"Prerequisite: MATH 102, 120, 210, or equivalent, or consent of instructor.","offering":"","sourcePage":173},"MATH 241":{"code":"MATH 241","title":"Calculus I","credits":"4","description":"Limits, continuity, implicit and explicit differentiation, extrema, increasing and decreasing functions, concavity, differentials, antiderivatives, basic integration theory (Riemann sums), and integration by substitution. Offered every spring. Prerequisite: MATH 140 or equivalent","offering":"Offered every spring.","sourcePage":174},"MATH 242":{"code":"MATH 242","title":"Calculus II","credits":"4","description":"Differentiation and integration of logarithmic, exponential, and trigonometric functions; applications of integration including area, volume, and arc length; techniques of integration; improper integrals, infinite series; conics, parametric equations, and polar coordinates. Offered every fall. Prerequisite: MATH 241","offering":"Offered every fall.","sourcePage":174},"MATH 332":{"code":"MATH 332","title":"College Geometry","credits":"3","description":"Basic concepts in Euclidean and non-Euclidean geometry, geometric transformations, and applications. Designed primarily for prospective mathematics teachers. Offered every third semester. Prerequisites: MATH 212 and MATH 242","offering":"Offered every third semester.","sourcePage":174},"MATH 335":{"code":"MATH 335","title":"Differential Equations","credits":"4","description":"First- and second-order methods for ordinary differential equations including separable, homogeneous, linear, Laplace transforms, linear systems, power series, and some applications. Offered spring of even years. Prerequisite: MATH 242","offering":"Offered spring of even years.","sourcePage":174},"MATH 336":{"code":"MATH 336","title":"Mathematical Statistics","credits":"3","description":"A mathematical study of probability and statistics. Course is Calculus-based and mixes theory and application. Students may not receive credit for both MATH 220 and MATH 336. Offered fall of odd years. Prerequisite: MATH 242; MATH 212 recommended","offering":"Offered fall of odd years.","sourcePage":174},"MATH 343":{"code":"MATH 343","title":"Calculus III","credits":"4","description":"Vectors and surfaces, parametric equations and motion, functions of several variables, partial differentiation, maximum- minimum, Lagrange multipliers, multiple integration, vector fields, path integrals, Green’s Theorem, and applications. Offered spring of odd years. Prerequisite: MATH 242","offering":"Offered spring of odd years.","sourcePage":174},"MATH 345":{"code":"MATH 345","title":"Numerical Analysis Methods","credits":"3","description":"Techniques for curve fitting, interpolation, numerical differentiation and integration; solutions of equations and systems of linear equations; polynomial approximation; error analysis and eigenvectors. Emphasis on the development of mathematical algorithms and data analysis techniques for solving problems encountered by engineers and scientists. Some solutions will be implemented in MATLAB or C/C++. Lab fee required. Offered every spring semester. Same as APCS 345 Prerequisites: MATH 241","offering":"Offered every spring semester.","sourcePage":174},"MATH 353":{"code":"MATH 353","title":"Linear Algebra","credits":"3","description":"Topics include matrices, systems of linear equations, determinants, vector spaces, inner products, linear transformations, eigen values and applications. A balance between axiomatic and computational mathematics. Offered every third semester. Prerequisites: MATH 212 and MATH 242","offering":"Offered every third semester.","sourcePage":175},"MATH 354":{"code":"MATH 354","title":"Abstract Algebra","credits":"3","description":"Elementary group theory and ring theory, fundamental isomorphism theorems, ideals, quotient rings, integral domains, real and complex numbers, factorization and zeros of polynomials. Offered every third semester. Prerequisites: MATH 212 and MATH 242; MATH 353 is also recommended","offering":"Offered every third semester.","sourcePage":175},"MATH 360":{"code":"MATH 360","title":"Selected Topics in Mathematics","credits":"3","description":"Various advanced mathematical topics can be studied depending on student and faculty interests. Topics will be different from those in courses already offered and will require some proof-writing. May be repeated once for credit. Prerequisite: MATH 212","offering":"","sourcePage":175},"MATH 390":{"code":"MATH 390","title":"Professional Development Seminar","credits":"2","description":"Readings and discussion of professional and ethical issues; preparation of an individual’s professional portfolio. Participation in a professional meeting and presentation of a paper based on original research and/or ideas encountered at the meeting. Offered every spring. Same as APCS/INDU/PHYS 390 Prerequisite: Junior standing in MATH or consent of instructor","offering":"Offered every spring.","sourcePage":175},"MATH 395":{"code":"MATH 395","title":"Professional Development Seminar II","credits":"1","description":"Continuation of professional development in a second area. Preparation of a professional portfolio; presentation of an individual research project or participation in another professional meeting and presentation of a research paper. Offered as needed. Pre/Co-requisite APCS 390/MATH 390","offering":"Offered as needed.","sourcePage":175},"MUAP 102":{"code":"MUAP 102","title":"Class Piano Instruction I (First Year Piano Skills)","credits":"1","description":"Designed for the beginning keyboardist with no previous experience. These courses are in a two-part series and must be taken in sequence, except with the instructor’s permission. Basic music and keyboarding skills will be taught including note reading, rhythm, scales, chords, harmonizing melodies and music interpretation. These fundamentals will allow students to explore any musical style. Elementary Education majors may find this class useful. Offered every fall.","offering":"Offered every fall.","sourcePage":176},"MUAP 105-111":{"code":"MUAP 105-111","title":"Private Instruction in Piano/Keyboard, Brass, Guitar/Bass, Percussion, Voice,","credits":"","description":"Woodwind, String 1 credit hour Instruction is offered for the beginning and advancing musician in twelve weekly, one-half hour lessons per semester. A private lesson tuition fee is charged. May be repeated for credit. Offered every fall and spring.","offering":"Offered every fall and spring.","sourcePage":175},"MUAP 130":{"code":"MUAP 130","title":"William Penn University Jazz Ensemble","credits":"1","description":"A contemporary music ensemble focusing on twentieth-century musical forms such as jazz, rock and world music. May be repeated for credit. Offered every fall and spring. Prerequisite: The equivalent of three years of high school ensemble playing or permission of instructor.","offering":"Offered every fall and spring.","sourcePage":176},"MUAP 131":{"code":"MUAP 131","title":"Marching/Pep Band","credits":"1","description":"Rehearsal and performance of typical pep band music, with required participation at home football games, including set up and tear down. The first rehearsal of this group will be held during the first week of classes, for an extended period. Prior to each home game, pep music will be played through at the regularly scheduled jazz ensemble rehearsal. Other performance opportunities will be taken under consideration by the director. Open to all qualified students at William Penn University and all qualified members of the local community. May be repeated for credit. Offered every spring.","offering":"Offered every spring.","sourcePage":176},"MUAP 140":{"code":"MUAP 140","title":"Music in the Electronic Medium","credits":"1","description":"A course in electro-acoustic music, focusing on creating, sequencing and recording original electronic music. Students will learn the basics of MIDI technology, recording, sequencing and editing software and apply them to their own original works. Each student will have a workstation with a computer and multi-timbral synthesizer for hands-on application in the music department MIDI Lab. Some piano/keyboard and/or computer/electronics experience is helpful but not required. May be taken 3 times to fulfill core Humanities requirement.","offering":"","sourcePage":176},"MUAP 202":{"code":"MUAP 202","title":"Class Piano Instruction II","credits":"1","description":"Continuation of Class Piano I. Prerequisites: MUAP 102 or consent of instructor","offering":"","sourcePage":176},"MUAP 250":{"code":"MUAP 250","title":"William Penn Singers (Choral Ensemble)","credits":"1","description":"Choral music from a wide variety of style periods from madrigals to sacred to vocal jazz/rock will be studied. Singers of all interests and levels are welcome to participate. It is assumed that students are enrolled in the ensemble for the full academic year. May be repeated for credit. Offered every fall and spring. Lab fee required.","offering":"Offered every fall and spring.","sourcePage":176},"MUAP 251":{"code":"MUAP 251","title":"William Penn Concert Band","credits":"1","description":"Symphonic concert band open to all William Penn University students, community members and area high school students. Performance of traditional and modern concert band literature. One major concert each semester plus graduation ceremony. May be repeated 8 times.","offering":"","sourcePage":177},"MUSI 100":{"code":"MUSI 100","title":"Applied Music Seminar","credits":"0","description":"A weekly convocation or studio class is held every Tuesday afternoon. Applied Music Seminar is an opportunity for students to perform with the permission of their applied music instructors. Students registered for any MUAP 101 section are required to attend. Held each semester.","offering":"","sourcePage":177},"MUSI 104":{"code":"MUSI 104","title":"Fundamentals of Music","credits":"3","description":"An introduction to the fundamentals of music theory, listening, appreciation, composition and improvisation with an emphasis on practical musicianship and hands-on learning. Exercises will include performance, composition and listening exercises. Keyboard experience is helpful but not required. Students may find it helpful to take the group piano class concurrently or study piano privately. Prerequisites: Previous musical experience (singing or playing) helpful.","offering":"","sourcePage":177},"MUSI 123":{"code":"MUSI 123","title":"Music Theory I","credits":"3","description":"The first of a two-course sequence focusing on fundamentals of notation, keys, diatonic chords, cadences and beginning formal analysis. Students not having sufficient keyboard ability should also study piano. Offered every fall.","offering":"Offered every fall.","sourcePage":177},"MUSI 124":{"code":"MUSI 124","title":"Music Theory II","credits":"3","description":"Continuation of MUSI 123. Seventh chords in root position and their inversions, non-chord tones, modulations, and work in improvisation and composition. MUSI 124 must follow MUSI 123 in sequence except with instructor’s permission. Offered every spring. Prerequisite: MUSI 123","offering":"Offered every spring.","sourcePage":177},"MUSI 201":{"code":"MUSI 201","title":"Woodwind Methods","credits":"1","description":"Woodwind Methods is a course designed to provide the music education major an introductory study, with actual playing experience, of the major woodwind instruments (Flute, clarinet and saxophone). Pedagogical approaches to these as well as double reed instruments will be examined and explored. Theoretical concepts such as transposition and the harmonic series will also be included in the course. This course is designed to enable the student to provide beginning instrumental instruction in either a public school or private studio setting. Prerequisite: MUSI 123 or consent of instructor","offering":"","sourcePage":177},"MUSI 202":{"code":"MUSI 202","title":"Brass Methods","credits":"1","description":"Brass Methods is a course designed to provide the music education major an introductory study, with actual playing experience, of the major brass instruments (trumpet, trombone, French horn and tuba). Pedagogical approaches to these instruments will be examined and explored. Theoretical concepts such as transposition and the harmonic series will also be included in the course. This course is designed to enable the student to provide beginning instrumental instruction in either a public school or private studio setting. Prerequisite: MUSI 123 or consent of instructor","offering":"","sourcePage":178},"MUSI 203":{"code":"MUSI 203","title":"String Methods","credits":"1","description":"String Methods is a course designed to provide the music education major an introductory study, with actual playing experience, of the major string instruments (violin, viola, cello and bass). Pedagogical approaches to these instruments will be examined and explored. Theoretical concepts such as transposition and the harmonic series will also be included in the course. This course is designed to enable the student to provide beginning instrumental instruction in either a public school or private studio setting. Prerequisite: MUSI 123 or consent of instructor","offering":"","sourcePage":178},"MUSI 204":{"code":"MUSI 204","title":"Percussion Methods","credits":"1","description":"Percussion Methods is a course designed to provide the music education major an introductory study, with actual playing experience, of the major percussion instruments (snare drum, keyboard percussion and timpani). Pedagogical approaches to these instruments will be examined and explored. Theoretical concepts such as transposition and the harmonic series will also be included in the course. This course is designed to enable the student to provide beginning instrumental instruction in either a public school or private studio setting. Prerequisite: MUSI 123 or consent of instructor","offering":"","sourcePage":178},"MUSI 216":{"code":"MUSI 216","title":"History of Music","credits":"3","description":"An introduction to Western music literature from early music to the present. Offered spring of even years. Prerequisite: Completion of MUSI 123 or instructor permission","offering":"Offered spring of even years.","sourcePage":178},"MUSI 217":{"code":"MUSI 217","title":"History of Music II","credits":"3","description":"Music in American from the time of the Puritans to the present day. Historical, biographical material and listening will be included. For the general students as well as for music majors and minors.","offering":"","sourcePage":178},"MUSI 223":{"code":"MUSI 223","title":"Music Theory III","credits":"3","description":"This course continues the study of the concepts introduced in Music Theory I and II, with the addition of augmented sixth chords, Neapolitan sixth chords, and changes of tonal centers. Prerequisites: MUSI 123 and MUSI 124","offering":"","sourcePage":178},"MUSI 224":{"code":"MUSI 224","title":"Music Theory IV","credits":"3","description":"This course studies counterpoint, fugues, sonata allegro, rondo, and variation forms, as well as 20th century chord structures and techniques. Prerequisites: MUSI 223","offering":"","sourcePage":179},"MUSI 336":{"code":"MUSI 336","title":"Conducting","credits":"2","description":"Instrumental and choral conducting and score reading, use of baton and rehearsal techniques, ranges of instruments, clefs, and transpositions. Offered fall semester of even-numbered years. Prerequisite: Student must also be concurrently enrolled in the William Penn University Jazz Ensemble (MUAP 130) and/or William Penn Singers (MUAP 250) and must have successfully completed MUSI 123.","offering":"Offered fall semester of even-numbered years.","sourcePage":179},"MUSI 337":{"code":"MUSI 337","title":"Conducting II","credits":"2","description":"Continuation of conducting studies with emphasis on instrumental conducting, baton technique, score reading/marking, transpositions, and rehearsal techniques. Offered spring semester of odd-numbered years. Prerequisite: MUSI 336.","offering":"Offered spring semester of odd-numbered years.","sourcePage":179},"MUSI 339":{"code":"MUSI 339","title":"Aural Skills I","credits":"2","description":"A skills course designed to improve the student’s aural acuity and sight-reading ability. Lab fee required. Offered fall of even years. Prerequisite: Concurrent enrollment in or completion of MUSI 123","offering":"Offered fall of even years.","sourcePage":179},"MUSI 340":{"code":"MUSI 340","title":"Aural Skills II","credits":"2","description":"This course is a continuation of the class Ear and Training and Sight Singing I. The content is designed to complement the Theory II course though it is not necessary they be taken in the same semester. This course is taught in the spring semester. Prerequisite: MUSI 339","offering":"","sourcePage":179},"NURS 201":{"code":"NURS 201","title":"Nursing Essentials","credits":"4","description":"This course introduces the essential scientific knowledge, technical skills, and communication techniques, as specified by OBRA, to function as an accountable member of the health care team. Theory, laboratory practice, and clinical experience will be incorporated to prepare the student to address the biopsychosocial and spiritual needs of patients. This is a 76-hour course (30 hours of lecture / 16 hours of lab / 30 hours of clinical). Background checks are required. Mandatory Reporter of Child and Dependent Adult Abuse, health physical and current immunizations, and TB testing will be required prior to clinical. Fees required. Prerequisites: None. Offered FA, SP, SU","offering":"","sourcePage":179},"NURS 202":{"code":"NURS 202","title":"Introduction to Nursing","credits":"2","description":"In this course, students will be encouraged to focus on self-care, stress-reduction and coping skills, test-taking strategies including TEAS exam preparation, and requirements for admission to the WPU Division of Nursing program. Students will also be introduced to professional writing and APA format. Fees required. Prerequisites: None.","offering":"","sourcePage":180},"NURS 210":{"code":"NURS 210","title":"Nutrition","credits":"3","description":"In this course, students will be introduced to nutrition terminology and explore nutrients, dietary guidelines, food labels, life cycle nutrition, and health promotion and disease management and prevention. Students will learn concepts of digestion, absorption, and energy obtained from food and begin to evaluate the nutritional status of clients across the lifespan. Fees required. Prerequisites: None.","offering":"","sourcePage":180},"NURS 214":{"code":"NURS 214","title":"Pharmacology","credits":"3","description":"This course will focus on basic medication classification, therapeutic and adverse effects, uses, interactions, contraindications, and methods of administration. Students will explore the nurse’s role in developing a comprehensive approach to the clinical application of drug therapy through use of the nursing process. Principles of safe administration of medications will be introduced. Dosage calculations are evaluated for competency. Fees required. Prerequisite: MATH 102 or 210 or equivalent","offering":"","sourcePage":180},"NURS 261":{"code":"NURS 261","title":"Guided Study","credits":"1-4","description":"This is an individually (or small group) designed course to expand the students’ experience or individual interest in some topic related to nursing. This course can be related to topics such as practice skills, diversity, health, or service to the community. The content of the course will be based on multilevel evidence that is supportive of the selected topic. Fees required. Prerequisites: None","offering":"","sourcePage":180},"NURS 299":{"code":"NURS 299","title":"Transition","credits":"2","description":"This course will serve as a transition for a student with past success in another nursing program who is transferring to William Penn University. Students will review foundational knowledge for nursing care. Assessment principles and proper documentation will be addressed. In addition, students will review foundational nursing skills and must demonstrate skills and assessment proficiency by the end of the course. Fees required. For LPN’s Prerequisites: None","offering":"","sourcePage":180},"NURS 300":{"code":"NURS 300","title":"Health Assessment/Pathophysiology for the RN-BSN","credits":"3","description":"This course focuses on pathophysiological aspects of alterations in major body systems at a cellular level. Emphasis is on the holistic nature of human responses to health alterations and how care impacts that human response. Understanding basic disease processes supports decision making in assessing, planning, implementing, and evaluating care of clients in professional nursing practice. Emphasis in this course is placed on comprehensive health assessment of individuals. Students will draw upon their prior knowledge in clinical experiences of health assessment to effectively conduct a comprehensive health assessment for providing safe, efficient care. Fees required. Prerequisite: Admission to RN-BSN Program","offering":"","sourcePage":183},"NURS 301":{"code":"NURS 301","title":"Professional Nursing for the RN-BSN","credits":"5","description":"This course enhances the students' understanding of clinical reasoning through expanding knowledge beyond pragmatic knowledge. Students will explore the concept of caring as uniquely expressed in their nursing situations. Students will learn to locate multi-level evidence, learn research terminology, types of research, and investigate evidence-based holistic nursing interventions. Students will begin utilizing APA formatting for professional writing. The student will be introduced to the ANA Standards of Practice and explore ethical issues that apply to nursing and information science. Prerequisite: Admission to RN-BSN Program","offering":"","sourcePage":184},"NURS 302":{"code":"NURS 302","title":"Nursing Leadership for the RN-BSN","credits":"4","description":"This course emphasizes concepts and skills of basic level management and leadership in nursing. Students will explore aspects of management/leadership with nurse leaders. The students will integrate concepts of critical thinking, decision-making, delegation, communication, and informatics to assure safety and quality outcome initiatives. This course prepares the student to assume the role of a manager/leader at the fundamental level. Fees required. Prerequisite: Admission to RN-BSN Program","offering":"","sourcePage":184},"NURS 303":{"code":"NURS 303","title":"Community Health Nursing for the RN-BSN","credits":"4","description":"This course focuses on examining the role of the nurse in understanding the community as a client. Students will come to know nursing assessment and interventions unique to the community or population-based settings. Within this course, students will explore global health and how they can impact the global community. Students will enhance their knowledge through clinical experiences in a variety of community settings. Prerequisite: Admission to RN-BSN Program","offering":"","sourcePage":184},"NURS 304":{"code":"NURS 304","title":"Nursing Fundamentals and Skills","credits":"4","description":"This course will introduce the student to foundational knowledge for nursing care. Students will learn theoretical and clinical applications for nursing skills. Utilizing hands-on experience in the lab setting, students will work closely with peers and faculty to demonstrate accurate and safe nursing skills delivery. Fees required. Prerequisites: NURS 201 or equivalent, NURS 214","offering":"","sourcePage":180},"NURS 306":{"code":"NURS 306","title":"Nursing Assessment","credits":"4","description":"This course is designed to present students with concepts and principles underlying assessment of the health status of individuals from newborn to geriatric. Emphasis is placed on interviewing skills, health histories, and the physical and psychosocial findings in the well person. Communication and assessment techniques are developed. Students will formulate initial nursing plans using the nursing process. Clinical application will enhance student learning. Fees required. Prerequisites: NURS 201 or equivalent, NURS 214","offering":"","sourcePage":181},"NURS 307":{"code":"NURS 307","title":"Professionalism in Nursing","credits":"3","description":"This course introduces the students to the concept of knowing beyond pragmatic knowledge. Students will explore the concept of caring as uniquely expressed in nursing situations. Students will become familiar with a variety of nursing theories and will begin utilizing APA formatting for professional writing. The student will be introduced to the ANA Standards of Practice and explore ethical issues that apply to nursing and information science. Prerequisites: NURS 201 or equivalent","offering":"","sourcePage":181},"NURS 308":{"code":"NURS 308","title":"Maternal, Newborn, and Women Nursing","credits":"4","description":"This course focuses on women, maternal, and newborn populations. Students will explore normal and abnormal conditions, nursing assessment, interventions, evaluation, and promotion of individual and family health for the population of interest. The student will have the opportunity to care for the described population in a clinical setting. Fees required. Prerequisite: NURS 304, NURS 306","offering":"","sourcePage":181},"NURS 309":{"code":"NURS 309","title":"Pediatric Nursing","credits":"4","description":"This course focuses on the infant to adolescent population. The student will be introduced to normal and abnormal conditions within the population. Nursing assessment, interventions, and evaluation of care for the population will be analyzed as well as the importance of health promotion. The student will have the opportunity to participate in care for the pediatric population in a variety of settings. Fees required. Prerequisite: NURS 304, NURS 306","offering":"","sourcePage":181},"NURS 310":{"code":"NURS 310","title":"Mental Health Nursing","credits":"4","description":"This course will help students identify the scope of psychiatric-mental health nursing practice, introducing the student to foundational knowledge for mental health nursing care. Students will discuss the importance of evidence-based psychiatric-mental health care in a variety of settings. Assessment principles and proper documentation will be addressed. In addition, students will observe treatment in a primary care setting, integrating physical and mental health issues in a holistic approach. Fees required. Prerequisite: NURS 304, NURS 306","offering":"","sourcePage":181},"NURS 312":{"code":"NURS 312","title":"Nursing Informatics for the RN-BSN","credits":"3","description":"The student will be introduced to information databases and explore ethical issues that apply to the use of information science in nursing. The student will analyze the use of information technology to support, identify, and assist in the application of patient care at an individual, organizational, and/or community level. Prerequisite: Admission into RN-BSN Program","offering":"","sourcePage":184},"NURS 313":{"code":"NURS 313","title":"Enhancing Nursing Health for the RN-BSN","credits":"3","description":"This course is designed to enhance the nurse's knowledge in holistic health. Students will learn concepts related to creating and maintaining a healthy life for the nurse and serve as a role model to their patients and community. Prerequisite: Admission to RN-BSN Program","offering":"","sourcePage":184},"NURS 316":{"code":"NURS 316","title":"Adult Health I","credits":"4","description":"In this course, students will explore themes and challenges in nursing practice while providing care based on evidence-based practice for adults with acute and chronic illnesses. Students will utilize the nursing process to identify priority patient problems and understand the nurse’s role in promoting self-care as well as nursing interventions to increase overall patient health. Ethical, legal, spiritual, and cultural values will be analyzed and integrated into a professional nursing care plan. Fees required. Prerequisite: NURS 304, NURS 306","offering":"","sourcePage":182},"NURS 320":{"code":"NURS 320","title":"Community Health Nursing","credits":"4","description":"This course focuses on examining the role of the nurse in understanding the community as a client. Students will come to know nursing assessments and interventions unique to the community or population-based setting. Within this course, students will explore global health and how they can impact the global community. Students will enhance their knowledge through clinical experiences in a variety of community settings. Fees required. Prerequisite: NURS 316","offering":"","sourcePage":182},"NURS 326":{"code":"NURS 326","title":"Adult Health II","credits":"4","description":"Adult Health II is a continuation of Adult Health I. In this course, students will explore themes and challenges in nursing practice while providing care based on evidence-based practice for adults with acute and chronic illnesses. Students will utilize the nursing process to identify priority patient problems and understand the nurse’s role in promoting self-care as well as nursing interventions to increase overall patient health. Ethical, legal, spiritual, and cultural values will be analyzed and integrated into a professional nursing care plan. Fees required. Prerequisite: NURS 316 NURS *** Assessment and Pathophysiology 3 credit hours This course examines alterations in normal physiologic processes and mechanisms underlying disease states across the lifespan. Emphasis is placed on pathophysiologic concepts, clinical manifestations, diagnostic findings, and implications for nursing care. Prerequisite: NURS 326, NURS 310, NURS 303, NURS 308, NURS 309","offering":"","sourcePage":182},"NURS 400":{"code":"NURS 400","title":"Introduction to Evidence Based Practice for the RN-BSN","credits":"2","description":"This course will introduce the concept of Evidence Based Practice. Students will learn to develop a clinical question, identify stakeholders, and gather evidence within the process of implementing Evidence Based Practice into nursing care. Prerequisites: Admission to RN-BSN Program, MATH 105 or MATH 220 or consent of instructor","offering":"","sourcePage":184},"NURS 403":{"code":"NURS 403","title":"Evidence Based Practice for the RN-BSN","credits":"3","description":"This course will allow students to focus on the process for implementing evidence-based practice and its application to a clinical situation generated from a practice setting of their choice. Students will utilize critical inquiry in evaluating and synthesizing multi-level evidence related to their question. This evidence will form the basis for drafts of policies to support EBP changes in their practice setting. Prerequisite: Admission to RN-BSN Program, NURS 400","offering":"","sourcePage":185},"NURS 414":{"code":"NURS 414","title":"Nursing Leadership","credits":"4","description":"This course emphasizes concepts and skills of basic level management and leadership in nursing. Students will explore aspects of management/leadership with nurse leaders. The students will integrate concepts of critical thinking, decision-making, delegation, communication, and informatics to assure safety and quality outcome initiatives. This course prepares the student to assume the role of a manager/leader at the fundamental level. Fees required. Prerequisite: Pre-Licensure Program – NURS 316","offering":"","sourcePage":183},"NURS 415":{"code":"NURS 415","title":"Evidence-Based Practice","credits":"3","description":"This course will allow students to focus on the process for implementing evidence-based practice and its application to a clinical situation generated from a practice setting of their choice. Students will utilize critical inquiry in evaluating and synthesizing multi-level evidence related to their question. This evidence will form the basis for drafts of policies to support EBP changes in their practice setting. The student will analyze the use of information technology to support, identify, and assist in the application of patient care across the healthcare continuum. Prerequisites: Pre-Licensure Program NURS 315, NURS 320","offering":"","sourcePage":183},"NURS 416":{"code":"NURS 416","title":"Adult Health III","credits":"3","description":"Adult Health III is a continuation of Adult Health I and Adult Health II. In this course, students will explore themes and challenges in managing nursing care in emergent and critical care situations. Students will utilize the nursing process to direct clinical decision-making based on evidence-based practice. Ethical, legal, spiritual, and cultural values will be analyzed and integrated into a professional nursing care plan. Prerequisite: NURS 326 RN-BSN Courses","offering":"","sourcePage":183},"PHLA 112":{"code":"PHLA 112","title":"Football","credits":"","description":"PHLA credit (1 hour) may also be earned by registering for and participating in the following intercollegiate athletics. Credit is awarded during the semester in which the season ends. These PHLA activities are graded on a credit/no credit basis.","offering":"","sourcePage":185},"PHLA 158":{"code":"PHLA 158","title":"Intercollegiate Football PHLA 171 Intercollegiate Lacrosse","credits":"","description":"PHLA 172 Intercollegiate Shooting","offering":"","sourcePage":185},"PHSC 100":{"code":"PHSC 100","title":"Physical and Earth/Space Science for Elementary Educators","credits":"3","description":"This course is designed to provide the Elementary Education student with an introduction to the Sciences with content related to Physical and Earth/Space Science. This class cannot be used to meet Core science requirements. Offered spring semester. Prerequisite: Elementary Education major","offering":"Offered spring semester.","sourcePage":185},"PHYS 201":{"code":"PHYS 201","title":"General Physics I","credits":"4","description":"Solid mechanics including kinematics, dynamics and statics; fluid mechanics, waves, periodic motion, sound, and light with algebra and trigonometry applications. Three lectures and one laboratory session per week. Lab fee required. Offered every fall. Prerequisite: MATH 140 or consent of instructor","offering":"Offered every fall.","sourcePage":186},"PHYS 202":{"code":"PHYS 202","title":"General Physics II","credits":"4","description":"Heat transfer, thermodynamics, magnetism; electricity including resistance, capacitance, inductance, series and parallel combinations, DC and AC circuits; electromagnetic waves, atomic structure and modern physics with algebra and trigonometry applications. Three lectures and one laboratory session per week. Lab fee required. Offered every spring. Prerequisite: PHYS 201","offering":"Offered every spring.","sourcePage":186},"PHYS 211":{"code":"PHYS 211","title":"College Physics I","credits":"5","description":"Solid mechanics including kinematics, dynamics and statics; fluid mechanics, waves, periodic motion, sound and light with vector and calculus applications. Three lectures, one laboratory session, and one problem- solving session per week. Lab fee required. Offered every fall. Prerequisite: MATH 241 or consent of instructor","offering":"Offered every fall.","sourcePage":186},"PHYS 212":{"code":"PHYS 212","title":"College Physics II","credits":"5","description":"Heat transfer, thermodynamics, magnetism; electricity including resistance, capacitance, inductance, series and parallel combinations, DC and AC circuits; electromagnetic waves, atomic structure and modern physics with vector and calculus applications. Three lectures, one laboratory session, and one problem-solving session per week. Lab fee required. Offered every spring. Prerequisite: PHYS 211","offering":"Offered every spring.","sourcePage":186},"PHYS 227":{"code":"PHYS 227","title":"Electrical Energy and Circuits","credits":"4","description":"Scientific theory of magnetism and electricity. An introduction to the generation and distribution of electrical energy. Application of Ohm’s Law and Watt’s Law to DC & AC circuits containing resistors, and/or capacitors, and/or inductors in series, parallel, and series/parallel combinations. Laboratory includes use of test equipment, breadboarding and troubleshooting of basic DC & AC circuits, and an introduction to residential wiring. Also includes units on Programmable Logic Controllers, basic electronics, and the construction of an individual project. Lab fee required. Offered every fall. Same as INDU 227 Prerequisite: MATH 140 recommended","offering":"Offered every fall.","sourcePage":186},"PHYS 327":{"code":"PHYS 327","title":"Engineering Thermodynamics","credits":"3","description":"Introduction to the principles of work, energy and the physical properties of engineering fluids including temperature, pressure, internal energy, enthalpy, specific heat and entropy. The first and second laws of thermodynamics will be studied and used to analyze various thermodynamic processes common in engineering practice. The non-flow energy equation, continuity equation, Bernoulli’s equation and steady flow energy equation will be introduced. Calculations will also involve the ideal gas law, gases, and gas mixtures, steam and non-ideal gases. Offered every fall. Same as ENGR 327 Prerequisites: MATH 140/MATH 241 and PHYS 202/212","offering":"Offered every fall.","sourcePage":187},"PHYS 333":{"code":"PHYS 333","title":"Industrial Electronics","credits":"4","description":"Scientific theory of semiconductors. An introduction to circuits using diodes, transistors, and op-amps. Exploration of the use of transducers to interface mechanical, fluid, electrical, and thermal systems with emphasis placed on industrial automation and control. Laboratory activities include breadboarding and troubleshooting basic circuits, use of Programmable Logic Controllers, and various forms of electric motor controls. Construction of individual and group projects including original design of a printed circuit board is encouraged. Lab fee required. Offered spring of even years. Same as INDU 333 Prerequisites: PHYS 202/212 or INDU 227","offering":"Offered spring of even years.","sourcePage":187},"PHYS 341":{"code":"PHYS 341","title":"Statics","credits":"3","description":"An introduction to the principles of engineering statics and the laws of equilibrium. Mathematical analysis of forces and moments acting on machine elements, frames and trusses at rest or in non-accelerated motion. The concepts of free body diagrams, inertia, friction and moment diagrams are introduced to help analyze multiple force systems. Classroom concepts will be applied to actual industrial problems to develop a method of problem evaluation and final solution. Lab fee required. Offered every spring. Same as ENGR 341 Prerequisites: PHYS 201/211 & MATH 241","offering":"Offered every spring.","sourcePage":187},"PHYS 342":{"code":"PHYS 342","title":"Dynamics and Kinematics","credits":"3","description":"An introduction to the principles of engineering dynamics, including particle position, displacement, velocity and acceleration. Newton’s laws will be used to evaluate the forces required to produce desired motions, velocities and accelerations of machine elements. Concepts of work, kinetic energy, impulse, momentum and the conservation of energy will be introduced and applied in the analysis of actual industrial problems. Lab fee required. Offered every spring. Same as ENGR 342 Prerequisites: PHYS 341","offering":"Offered every spring.","sourcePage":187},"PHYS 343":{"code":"PHYS 343","title":"Mechanics of Materials","credits":"3","description":"An introduction to the concept of internal stresses in machine elements resulting from applied external force systems. Mathematical analysis of tension, compression, torsional and flexure stresses in machine elements and pressure vessels. Introduction and mathematical analysis of strain and deflections resulting from external forces. Classroom concepts will be applied to actual industrial problems to develop a method of problem evaluation and resolution. Offered every fall. Same as ENGR 343 Prerequisites: PHYS 341","offering":"Offered every fall.","sourcePage":187},"PHYS 390":{"code":"PHYS 390","title":"Professional Development Seminar","credits":"2","description":"Readings and discussion of professional and ethical issues; preparation of an individual’s professional portfolio. Participation in a professional meeting and presentation of a paper based on original research and/or ideas encountered at the meeting. Offered spring semester. Same as APCS/INDU/MATH 390 Prerequisite: Junior standing in PHYS or consent of instructor","offering":"Offered spring semester.","sourcePage":188},"PHYS 395":{"code":"PHYS 395","title":"Professional Development Seminar II","credits":"1","description":"Continuation of professional development in a second area. Preparation of a professional portfolio; presentation of an individual research project or participation in another professional meeting and presentation of a research paper. Offered as needed. Pre/Co-requisite: APCS/INDU/MATH 390","offering":"Offered as needed.","sourcePage":188},"PLSC 100":{"code":"PLSC 100","title":"International Relations","credits":"3","description":"Individual, domestic, national and system effects on relations between states; war, diplomacy and other instruments of influence; contemporary and future international problems. Offered every spring.","offering":"Offered every spring.","sourcePage":188},"PLSC 125":{"code":"PLSC 125","title":"United States National Government","credits":"3","description":"Nature of government, Federal Constitutional principles; organization and functions of executive, legislative, and judicial branches; roles of interest groups and citizens in democracy. Offered every fall.","offering":"Offered every fall.","sourcePage":188},"PLSC 150":{"code":"PLSC 150","title":"Comparative Politics -Western Democracies","credits":"3","description":"The politics of Great Britain, France, the Federal Republic of Germany, and other major Western European states; the comparative method and its utility in the study of politics, comparison of political processes and political institutions. Offered spring of even years.","offering":"Offered spring of even years.","sourcePage":188},"PLSC 200":{"code":"PLSC 200","title":"The Politics of War and Peace","credits":"3","description":"Major issues concerning war and peace and the search for peace; research on the causes of war at the individual, national and system levels; an examination of the ethics of war and the conduct of war; nuclear weapons and disarmament, nuclear war. Prerequisite: PLSC 100 or consent of instructor","offering":"","sourcePage":188},"PLSC 210":{"code":"PLSC 210","title":"State and Local Government","credits":"3","description":"Organization and functions of state, county, and municipal government; examination of their financial problems, reorganization and urban-rural relations. Offered spring of odd years.","offering":"Offered spring of odd years.","sourcePage":188},"PLSC 217":{"code":"PLSC 217","title":"Ethnic and Race Relations","credits":"3","description":"Explores the historic and current problems faced by ethnic and racial minority groups in American society; the causes and consequences of prejudice and discrimination and the nature of current minority-majority interaction. Offered fall of even years. Same as SOCI 217","offering":"Offered fall of even years.","sourcePage":189},"PLSC 221":{"code":"PLSC 221","title":"Women in American History","credits":"3","description":"Examines the political, economic, social, and cultural history of American women. Offered spring of even years. Same as HIST/SOCI 221","offering":"Offered spring of even years.","sourcePage":189},"PLSC 230":{"code":"PLSC 230","title":"Congress and the Presidency","credits":"3","description":"Background of the executive and legislative branches in the Constitutional Convention and their evolution to present; decision-making by Congress and the President. Offered fall of even years. Prerequisite: PLSC 125 or consent of instructor","offering":"Offered fall of even years.","sourcePage":189},"PLSC 234":{"code":"PLSC 234","title":"African American History","credits":"3","description":"Examines the political, economic, social, and cultural history of African-Americans. Same as HIST/SOCI 234","offering":"","sourcePage":189},"PLSC 236":{"code":"PLSC 236","title":"America in the Modern World","credits":"3","description":"Examines the diplomatic and military history of the United States since the Revolutionary War, with emphasis on the twentieth century. Same as HIST 236","offering":"","sourcePage":189},"PLSC 250":{"code":"PLSC 250","title":"American Political Parties and Elections","credits":"3","description":"Examines the historical development, organization, functions, and tactics of American political parties and the historical development, method, style, and meaning of presidential and congressional election campaigns. Same as HIST 250","offering":"","sourcePage":189},"PLSC 310":{"code":"PLSC 310","title":"Political Thought","credits":"3","description":"Analysis of political theory from the ancient, medieval, modern, and post-modern periods, with application to political issues and problems of the contemporary world. Offered fall of odd years.","offering":"Offered fall of odd years.","sourcePage":189},"PLSC 321":{"code":"PLSC 321","title":"U.S. Public Opinion and Interest Groups","credits":"3","description":"An examination of the trends and diversity of American public opinion on political issues; an introduction to the measurement of public opinion; how and why public opinion develops into interest groups; types, resources, tactics, roles, and regulation of interest groups.","offering":"","sourcePage":189},"PLSC 331":{"code":"PLSC 331","title":"Law and Society","credits":"3","description":"Evolution of law and legal institutions; theory of law and jurisprudence; use of law and the legal system for the development of public policy. Offered odd years. Same as SOCI 331 Prerequisite: PLSC 125 or consent of instructor","offering":"Offered odd years.","sourcePage":190},"PLSC 332":{"code":"PLSC 332","title":"American Constitutional History","credits":"3","description":"Examines the historical development of the U. S. Supreme Court and its major decisions since the Federalist era. Offered fall of odd years. Same as HIST 332","offering":"Offered fall of odd years.","sourcePage":190},"PLSC 333":{"code":"PLSC 333","title":"Constitutional Rights and Liberties","credits":"3","description":"Legal issues, controversies, and significant developments in constitutional rights and liberties, and the impact of these developments upon American politics, culture, and social institutions. Offered fall of even years. Prerequisite: PLSC 125, or PLSC 332, or consent of instructor","offering":"Offered fall of even years.","sourcePage":190},"PLSC 349":{"code":"PLSC 349","title":"International Business","credits":"3","description":"Study of business in a global economy with the major complexities involved including the effects of different social systems, governmental influences on trade, financial exchange rates, and corporate relationships and policies. Offered every spring. Same as ECON/BUSI 349 Prerequisites: Junior standing","offering":"Offered every spring.","sourcePage":190},"PLSC 358":{"code":"PLSC 358","title":"Washington Center Internship","credits":"","description":"10 to 15 credit hours The Washington Center places juniors or first semester seniors in a federal agency in Washington, D.C. Interns work forty hours per week in a responsible position for twelve hours credit and participate in one weekly seminar led by a professional practitioner for three hours credit. Applications are due April 15 for the fall semester, October 1 for the spring semester, and February 15 for the summer (summer session credit ten hours maximum).","offering":"","sourcePage":190},"PLSC 359":{"code":"PLSC 359","title":"Iowa Legislative Internship","credits":"","description":"6 to 12 credit hours Interns spend spring semester at Iowa State Legislature in Des Moines, gaining practical experience in the legislative process and providing useful staff services for legislators. Interns serve either Monday through Thursday for twelve hours credit or two of those days for six hours credit. Interns must submit paper summarizing legislative experience. All applications are due December 1.","offering":"","sourcePage":190},"PLSC 390":{"code":"PLSC 390","title":"History/Government Practicum","credits":"3","description":"This capstone course integrates knowledge gained through student’s major concentration and Penn Leadership Core courses. Offered every spring. Same as HIST 390","offering":"Offered every spring.","sourcePage":190},"PSYC 102":{"code":"PSYC 102","title":"Introduction to Psychology","credits":"3","description":"Introductory psychology with units in learning, human development, problem solving, perception, emotion, motivation, personality, social behavior, behavior disorders, and therapy. Offered every fall.","offering":"Offered every fall.","sourcePage":191},"PSYC 108":{"code":"PSYC 108","title":"Lifespan Psychology","credits":"3","description":"Human development from conception to death (child, adolescent, adult psychology). Emphasis on the plasticity, multidimensionality, multi-directionality, and historical embeddedness of human change. Offered every fall and spring.","offering":"Offered every fall and spring.","sourcePage":191},"PSYC 221":{"code":"PSYC 221","title":"Introduction to Counseling","credits":"3","description":"An overview of current practices in personal and career counseling including basic counseling skills and contemporary professional issues. Emphasis on service to individuals. Offered every fall.","offering":"Offered every fall.","sourcePage":191},"PSYC 230":{"code":"PSYC 230","title":"Psychology of Religion","credits":"3","description":"A course that examines the practice of religion from a social scientific perspective. Same as RELI 230","offering":"","sourcePage":191},"PSYC 240":{"code":"PSYC 240","title":"Health Psychology","credits":"3","description":"Psychological contributions to understanding the causes, prevention, and treatment of physical illness. Research addressing the reciprocal effects of behavior and physical health will be emphasized. Offered spring.","offering":"Offered spring.","sourcePage":191},"PSYC 260":{"code":"PSYC 260","title":"Social Psychology","credits":"3","description":"Scientific study of social influence. Topics include small group process, organizational behavior, affliction, aggression, altruism, attitude change, interpersonal attractions, and prejudice. Offered every spring. Same as SOCI 260","offering":"Offered every spring.","sourcePage":191},"PSYC 265":{"code":"PSYC 265","title":"Social Science Statistics","credits":"3","description":"This course introduces students to the fundamentals of social statistics–techniques social scientists use to summarize quantitative data. The topics include descriptive statistical percentages, ratios and rates, frequency distributions, tables, charts, and graphs; measures of central tendency and dispersion; inferential statistical sampling distribution and estimation; hypothesis testing; bivariate measures of association; and multivariate techniques. Offered every fall. MATH 105 recommended. Same as SOCI 265","offering":"Offered every fall.","sourcePage":191},"PSYC 303":{"code":"PSYC 303","title":"Developmental & Educational Psychology","credits":"3","description":"This course focuses on human development of child and adolescent (K-12) including physical, personal, social and cognitive development. Psychological principles are applied to the educational process with units in learning, motivation, measurement, and evaluation. This course is required for all education majors. Prerequisites: EDUC 100, Junior standing or consent of the instructor","offering":"","sourcePage":191},"PSYC 305":{"code":"PSYC 305","title":"Theories and Systems of Counseling","credits":"3","description":"The emphasis of this course is counseling theories as applied to counseling individuals. An overview of the major theoretical perspectives on human behavior and individual counseling interventions. Counseling strategies and techniques associated with different theories will be discussed. Offered every spring. Prerequisite: PSYC 102","offering":"Offered every spring.","sourcePage":192},"PSYC 322":{"code":"PSYC 322","title":"Multicultural Counseling Approaches","credits":"3","description":"Designed to help counselors and mental health practitioners maximize their effectiveness when working with a culturally diverse population. Offered every spring. Prerequisite: PSYC 221","offering":"Offered every spring.","sourcePage":192},"PSYC 326":{"code":"PSYC 326","title":"Abnormal Psychology","credits":"3","description":"A study of major forms of psychological disorder in adults and children in the context of modern life. Attention to the genetic, socio-cultural, and psychological bases and amelioration of abnormality. Offered every spring.","offering":"Offered every spring.","sourcePage":192},"PSYC 327":{"code":"PSYC 327","title":"Personality","credits":"3","description":"A survey of the major theories of personality, including but not limited to those of Freud, Jung, Skinner, Maslow, Adler, Fromm, Bandura, Allport, and Cattell. Offered every fall. Prerequisites: PSYC 102 or consent of instructor","offering":"Offered every fall.","sourcePage":192},"PSYC 331":{"code":"PSYC 331","title":"Human Services in Contemporary America","credits":"3","description":"Survey of human service organizations, their historical development, relationship to professional societies, and diverse employment opportunities locally and nationally. Offered every fall.","offering":"Offered every fall.","sourcePage":192},"PSYC 333":{"code":"PSYC 333","title":"Learning","credits":"3","description":"An exploration of past and current learning theories. Emphasis will be placed on how learning principles are related to everyday experiences and how knowledge of these principles may be used to modify one’s behavior for a more satisfying life. Offered every fall. Prerequisite: PSYC 102 or consent of instructor","offering":"Offered every fall.","sourcePage":192},"PSYC 335":{"code":"PSYC 335","title":"Experimental Psychology","credits":"3","description":"An in-depth examination of research methods applied in the field of psychology, as well as how data is collected, analyzed (at a basic level) and written in report form. Required of psychology majors. Offered every fall. Prerequisite: PSYC 102 and MATH 220 or consent of instructor","offering":"Offered every fall.","sourcePage":192},"PSYC 348":{"code":"PSYC 348","title":"Crisis Intervention","credits":"3","description":"A skills-related counseling course to understand the bases of and practical techniques for crisis intervention and group facilitation. Offered every spring. Prerequisite: PSYC 102","offering":"Offered every spring.","sourcePage":193},"PSYC 390":{"code":"PSYC 390","title":"Psychology Practicum Human Services General","credits":"3","description":"A capstone course for psychology / human services majors. Some field experience and seminar discussion. Human services students will be required to work a minimum of 100 hours in an area of human services or a work setting where human relations skills and psychological knowledge are relevant. Psychology students will conduct primary or literature research integrating knowledge in their discipline. Offered every spring. Prerequisite: PSYC 335 for Psychology majors","offering":"Offered every spring.","sourcePage":193},"RELI 104":{"code":"RELI 104","title":"Understanding the Old Testament","credits":"3","description":"A survey course in which significant portions of the Old Testament are read and discussed. The historical- spiritual development of the Jewish people and relationship of the Jewish faith to Christianity is emphasized.","offering":"","sourcePage":193},"RELI 106":{"code":"RELI 106","title":"Understanding the New Testament","credits":"3","description":"A survey course in which the entire New Testament is read and discussed. Major features and themes of the individual books and letters of the New Testament are discussed and analyzed.","offering":"","sourcePage":193},"RELI 204":{"code":"RELI 204","title":"Christianity in America","credits":"3","description":"Examines the rise of both the Protestant and Catholic churches in America and the influence of Christianity upon American life and culture. Same as HIST 204","offering":"","sourcePage":193},"RELI 206":{"code":"RELI 206","title":"Christian Ethics","credits":"3","description":"This course examines the foundations of Christian ethical thought and theory derived from both the New and Old Testaments. The personal and social implications of Christian ethics to life and culture will be addressed. Lives of exemplars representing Christian ethics in action–both past and present–will serve as models for study and reflection.","offering":"","sourcePage":193},"RELI 210":{"code":"RELI 210","title":"Religion in Modern America","credits":"3","description":"A survey of the influence of religion upon American culture from the 20th century to the present day.","offering":"","sourcePage":193},"RELI 212":{"code":"RELI 212","title":"Religion and Society","credits":"3","description":"This course approaches religion as one of society’s institutions. It will focus on the practices, social structures, historical backgrounds, development, universal themes and the roles of religion in society. Emphasis will be placed on the dialectical relationship between society and religion. Same as SOCI 212","offering":"","sourcePage":194},"RELI 230":{"code":"RELI 230","title":"Psychology of Religion","credits":"3","description":"A course that examines the practice of religion from a social scientific perspective. Same as PSYC 230","offering":"","sourcePage":194},"RELI 300":{"code":"RELI 300","title":"Comparative Religion","credits":"3","description":"This course is a comparative survey of world religious leaders, historical and contemporary. The emphasis will be on understanding the major religious faiths of the world. The course will include inquiry concerning the beliefs, practices, views of reality, morality, paths of ultimate fulfillment, and the social implications of the world’s major religions. Students will be expected to respond reflectively to the readings and field experiences.","offering":"","sourcePage":194},"SMGT 222":{"code":"SMGT 222","title":"American Sports History","credits":"3","description":"Examines the history of American sports aside from baseball, with emphasis on the twentieth century. Same as HIST 222","offering":"","sourcePage":194},"SMGT 228":{"code":"SMGT 228","title":"Sport Communication","credits":"3","description":"An introduction and overview of the field of sport communication; specific topics include models of sport communication, print and electronic media, sport advertising, public relations, media relations, and employment opportunities. Students will write copy for various media) create content for their sport communication portfolio) as well as critically assess content created by other sport organizations. Theory of Coaching Sports Courses The following 2 credit hour theory courses include the theory, organization, methods and techniques of coaching these sports. Each course is designed as preparation for public school coaching. Lectures and practical work with the various athletic teams are included. Also included will be ethics education for coaches of all sports.","offering":"","sourcePage":194},"SMGT 250":{"code":"SMGT 250","title":"Theory of Coaching Soccer","credits":"","description":"SMGT 251 Theory and Practice of Officiating Students will obtain proficiencies in the fundamentals, techniques, rules, procedures, and professional attitudes required of officials for football, basketball, baseball, softball, and volleyball. Offered fall & spring semesters.","offering":"Offered fall & spring semesters.","sourcePage":195},"SMGT 253":{"code":"SMGT 253","title":"Theory of Mental Training","credits":"2","description":"This course will dive into mental training practices to achieve success on sports teams and in business and in life. The goal is to teach theories and practices that students can take with them in their respective sport and future coaching of business endeavors.","offering":"","sourcePage":195},"SMGT 260":{"code":"SMGT 260","title":"Field Experience I","credits":"1","description":"An opportunity for students to survey pre-career opportunities, observe industry-relevant practices and content, and initiate professional networking. Course is repeatable once for credit;2 credit hours maximum.","offering":"","sourcePage":195},"SMGT 319":{"code":"SMGT 319","title":"Concepts of Coaching","credits":"3","description":"This course provides an overview of the concepts that are essential in the preparation of sport coaches in secondary schools. Students will evaluate the current theoretical perspectives in the field of sport psychology and critically evaluate the current research in coaching sports. Topics include: developing a coaching philosophy, evaluating theories in motivation, understanding team dynamics, communicating effectively, and improving player performance. Offered fall semester. Prerequisite: Junior standing","offering":"Offered fall semester.","sourcePage":195},"SMGT 321":{"code":"SMGT 321","title":"Sports Marketing","credits":"3","description":"Marketing concepts applied to the sports industry with application emphasis on the amateur and collegiate levels. Topics covered include the traditional marketing mix, services marketing, public relations, and event planning. Students also will utilize case studies and individual and team projects in learning how to market sporting events. Same as BUSI 321 Prerequisite: Junior standing or consent of instructor.","offering":"","sourcePage":195},"SMGT 351":{"code":"SMGT 351","title":"Paradigms in Sport","credits":"3","description":"A systematic assessment of contemporary sport programs focusing on the development and application of leadership skills across various sport platforms. Topics include a historical overview of sport, examination of necessary management skills, exploration of different sports and settings, and the progression of leadership expertise necessary for success in the industry. Offered every spring/fall; occasional summer. Prerequisite: Junior standing or consent of instructor.","offering":"Offered every spring/fall; occasional summer.","sourcePage":195},"SMGT 360":{"code":"SMGT 360","title":"Field Experience II","credits":"1","description":"An opportunity for students to further explore practice-based opportunities, develop industry-relevant skills and initiate networking, as well as building their career portfolio in the sport industry. Course is repeatable once for credit; 2 credit hours maximum.","offering":"","sourcePage":196},"SMGT 445":{"code":"SMGT 445","title":"Sport Facility & Event Management","credits":"3","description":"This course examines the fundamental knowledge, skills, and concepts pertaining to the planning, organization, publicity, and management of sporting events. Additionally, the course will address the ongoing operation, maintenance, development, and planning of sport and leisure facilities. Offered fall. Prerequisite: Sport Management majors only; others by permission of instructor.","offering":"Offered fall.","sourcePage":196},"SMGT 454":{"code":"SMGT 454","title":"Fundamental Legal Topics in Kinesiology","credits":"3","description":"This course focuses on safety, negligence, and liability in sport. Designed to help ADs, coaches, educators, facility managers, program directors, etc., develop the knowledge and skills to recognize and eliminate dangerous situations before they become problematic. Offered spring. Prerequisite: Sport Management majors only; others by permission of instructor.","offering":"Offered spring.","sourcePage":196},"SOCI 101":{"code":"SOCI 101","title":"Introduction to Sociology","credits":"3","description":"Examines the social processes and structures which shape both individuals and groups of all sizes, including friends, families, corporations and nations. Provides students with interpretive tools for understanding themselves and others in a changing world. Offered every fall.","offering":"Offered every fall.","sourcePage":196},"SOCI 123":{"code":"SOCI 123","title":"Sociology of Contemporary Issues","credits":"3","description":"Investigates current social problems with an analysis of causative factors and possible solutions. Topics covered will vary. Offered every spring.","offering":"Offered every spring.","sourcePage":196},"SOCI 126":{"code":"SOCI 126","title":"Deviant Behavior","credits":"3","description":"A sociological analysis of deviant behavior in relation to norms, values, and social control. The course examines the relationship of deviant behavior to conventional values, sex roles, institutions, and power, with special attention to the social construction of deviance. Offered spring of even years.","offering":"Offered spring of even years.","sourcePage":196},"SOCI 211":{"code":"SOCI 211","title":"Introduction to Criminology","credits":"3","description":"Analyzes the meaning, identification and causes of crime and the role of social institutions in the control of crime and the correction of criminals. Offered every fall.","offering":"Offered every fall.","sourcePage":196},"SOCI 212":{"code":"SOCI 212","title":"Religion and Society","credits":"3","description":"This course approaches religion as one of society’s institutions. It will focus on the practices, social structures, historical backgrounds, development, universal themes and the roles of religion in society. Emphasis will be placed on the dialectical relationship between society and religion. Same as RELI 212","offering":"","sourcePage":197},"SOCI 217":{"code":"SOCI 217","title":"Ethnic and Race Relations","credits":"3","description":"Explores the historic and current problems faced by ethnic and racial minority groups in American society and beyond; the causes and consequences of prejudice and discrimination and the nature of current minority- majority interaction. Offered fall of even years. Same as PLSC 217","offering":"Offered fall of even years.","sourcePage":197},"SOCI 218":{"code":"SOCI 218","title":"Juvenile Delinquency","credits":"3","description":"An investigation of youth as both offenders and victims of crime; theories of juvenile delinquency; youth programs related to crime; the role of the school, the family, and the police; child abuse, runaways and street kids; juvenile gangs; the juvenile justice system; juvenile corrections, and an evaluation of preventive programs. Offered every fall.","offering":"Offered every fall.","sourcePage":197},"SOCI 219":{"code":"SOCI 219","title":"Sex and Gender in Society","credits":"3","description":"A sociological exploration of the changing roles of men and women. Examination of formation of male and female identity; problems encountered between men and women; interpersonal, romantic, and work relationships; and the implications of changing sex roles for major social institutions. Offered every spring.","offering":"Offered every spring.","sourcePage":197},"SOCI 220":{"code":"SOCI 220","title":"Social Organization","credits":"3","description":"A study of organizational society, its formal and informal structure, the development of bureaucracy, and the use and misuse of power. Offered fall of odd years.","offering":"Offered fall of odd years.","sourcePage":197},"SOCI 221":{"code":"SOCI 221","title":"Women in American History","credits":"3","description":"Examines the political, economic, social, and cultural history of American women. Same as HIST 221/PLSC 221","offering":"","sourcePage":197},"SOCI 223":{"code":"SOCI 223","title":"Sociology of Sport","credits":"3","description":"This course offers a sociological examination and analysis of the role the institution, sport, plays in social life and society. Particular attention is given to understanding the social processes which relate to sport, such as socialization, competition and conflict, cooperation, social stratification, and social change. Additionally, the relationship(s) between sport and culture and between sport and other social institutions–such as education, economics, politics, health, family, and religion–is addressed. Offered spring of odd years. Same as SMGT 223","offering":"Offered spring of odd years.","sourcePage":197},"SOCI 234":{"code":"SOCI 234","title":"African American History","credits":"3","description":"Examines the political, economic, social, and cultural history of African-Americans. Same as PLSC/HIST 234","offering":"","sourcePage":197},"SOCI 240":{"code":"SOCI 240","title":"Policing in America","credits":"3","description":"This course examines fundamental issues relevant to contemporary public policing in the United States. Included in this examination are the role and history of police and policing; the impact of policing on crime, disorder, and other social problems; discretion and its control; moral hazards of the profession; police legitimacy and public support; police culture and organization; community policing strategies; and the homeland security role. Offered fall semester.","offering":"Offered fall semester.","sourcePage":198},"SOCI 242":{"code":"SOCI 242","title":"Crime and Public Policy","credits":"3","description":"Crime control in America focuses on the research regarding the effectiveness of various crime control programs. This course is designed to provide students with a broad analysis of both historic and contemporary crime control strategies implemented by the police, courts, legislators, and the correctional system. Studies indicating strengths and weaknesses of each strategy are examined. Special approaches outside the criminal justice system are reviewed, as well as juvenile crime issues. Offered spring semester.","offering":"Offered spring semester.","sourcePage":198},"SOCI 260":{"code":"SOCI 260","title":"Social Psychology","credits":"3","description":"Scientific study of social influence. Topics include small group process, organizational behavior, affliction, aggression, altruism, attitude change, interpersonal attractions, and prejudice. Same as PSYC 260","offering":"","sourcePage":198},"SOCI 265":{"code":"SOCI 265","title":"Social Science Statistics","credits":"3","description":"This course introduces students to the fundamentals of social statistics–techniques social scientists use to summarize quantitative data. The topics include descriptive statistical percentages, ratios and rates, frequency distributions, tables, charts, and graphs; measures of central tendency and dispersion; inferential statistical sampling distribution and estimation; hypothesis testing; bivariate measures of association; and multivariate techniques. Offered every fall. MATH 105 recommended. Same as PSYC 265","offering":"Offered every fall.","sourcePage":198},"SOCI 311":{"code":"SOCI 311","title":"Marriage and Family","credits":"3","description":"Marriage and contemporary family life; exploration of questions, problems, and alternatives. Offered every fall. Prerequisite: SOCI 101, or SOCI 123, or consent of instructor","offering":"Offered every fall.","sourcePage":198},"SOCI 328":{"code":"SOCI 328","title":"Criminology Theory and Practice","credits":"3","description":"An analysis of the patterns and causes of criminality and the operational practice of the law enforcement and criminal justice systems. Crime, as a form of social deviance, is examined in relation to the cultural and social control systems of society. Offered every spring. Prerequisite: SOCI 101, 123, or consent of instructor","offering":"Offered every spring.","sourcePage":198},"SOCI 331":{"code":"SOCI 331","title":"Law and Society","credits":"3","description":"Evolution of law and legal institutions; theory of law and jurisprudence; use of law and the legal system for the development of public policy. Same as PLSC 331 Prerequisite: PLSC 125 or consent of instructor","offering":"","sourcePage":199},"SOCI 335":{"code":"SOCI 335","title":"Social Research Methods","credits":"3","description":"Presents the detailed logic underlying research design, data collection, and data analysis in sociological studies. The course addresses both quantitative (e.g., survey) and qualitative (e.g., participant observation) dimensions of research, and special emphasis is placed on research ethics. Offered every spring. Prerequisite: MATH 105 or consent of instructor","offering":"Offered every spring.","sourcePage":199},"SOCI 345":{"code":"SOCI 345","title":"Organizational Behavior","credits":"3","description":"Analysis of the behavior of people in organizations, drawing upon the disciplines of Psychology, Sociology, and Business Administration. Applications are studied in the context of effective management of organizational behavior and the important inter-relationships between needs and expectations of the individual, the organization, and society. Offered every fall. Same as BUSI 345","offering":"Offered every fall.","sourcePage":199},"SOCI 347":{"code":"SOCI 347","title":"Business Ethics","credits":"3","description":"Approaches to ethical issues and problems facing business and society today. Offered every fall and spring. Same as BUSI 347 Prerequisite: Junior standing","offering":"Offered every fall and spring.","sourcePage":199},"SOCI 350":{"code":"SOCI 350","title":"Sociological Theory","credits":"3","description":"An integrative seminar focusing on the central issues and selected problems faced by major social thinkers and others in the study and understanding of the social world. Offered every fall. Prerequisite: SOCI 101 or SOCI 123 and twelve hours of other Sociology courses, or consent of the instructor","offering":"Offered every fall.","sourcePage":199},"SOCI 390":{"code":"SOCI 390","title":"Sociology Practicum","credits":"3","description":"A capstone seminar course in sociology research methodology, theory, and practice involving 100 hours of relevant service learning. Regardless of emphasis area, majors will be involved in research integrating knowledge of their discipline with critical reflection on their service learning experiences. Offered every spring.","offering":"Offered every spring.","sourcePage":199},"THEA 104":{"code":"THEA 104","title":"Basic Production","credits":"3","description":"Designed to familiarize a student with all production aspects of a working theatre. Along with class and workshop time, students will make practical application of theories and practices through work on university, community, and possibly, professional performances. Offered fall semester.","offering":"Offered fall semester.","sourcePage":200},"THEA 106":{"code":"THEA 106","title":"Acting I","credits":"3","description":"Students will explore basic acting techniques as they relate to theatre productions, and a variety of post- graduate and/or occupational scenarios. Techniques covered include character analysis, script analysis, voice projection, movement, collaboration, communication, memorization, and creativity. Offered spring semester.","offering":"Offered spring semester.","sourcePage":200},"THEA 110":{"code":"THEA 110","title":"Improvisation and Movement","credits":"3","description":"Students will explore basic performing techniques as they relate to theatrical productions, and a variety of post- graduate and/or occupational scenarios. Short-form improvisation techniques will be the primary focus of the course. Offered fall semester.","offering":"Offered fall semester.","sourcePage":200},"THEA 114":{"code":"THEA 114","title":"Theatre Production","credits":"1","description":"This course will allow students to utilize their theatrical skills and knowledge on actual university productions. Students must participate in the production(s) being done in the semester the course is offered.","offering":"","sourcePage":200},"THEA 119":{"code":"THEA 119","title":"Specialized Production Elements","credits":"3","description":"This course explores basic principles, designs, and implementation related to special technical areas of theatrical productions. These areas include special effects, makeup, and costuming. Students must make practical application of course content through participation in the university production(s) being done in the semester the course is offered.","offering":"","sourcePage":200},"THEA 124":{"code":"THEA 124","title":"Stage Lighting & Sound","credits":"3","description":"An introductory course providing students with a basic understanding of the principles, practices, and execution of stage lighting and sound and their applications in the theatre. The lighting portion of the course focuses on the fundamentals of stage lighting such as: functions of lighting, qualities of light, design, basic electricity, lighting instruments and equipment, light plot basics, board operation, and safety. The sound portion of the course provides the students with a working knowledge of sound design and engineering focusing on the functions of sound, equipment (including set up and maintenance), design, sound operation, sound plot basics, recording and reproduction.","offering":"","sourcePage":200},"THEA 130":{"code":"THEA 130","title":"Scenic Design and Construction","credits":"3","description":"This course is designed to familiarize students with all production aspects of designing, building, and painting a set. Along with class and workshop time, students will make practical application of theories and practices through work on university, community, and professional performances.","offering":"","sourcePage":201},"THEA 212":{"code":"THEA 212","title":"Oral Interpretation","credits":"3","description":"This course will introduce students to a specific, systematic understanding of performed literature. An emphasis will be placed on connecting the analytical and presentational skills utilized in Oral Interpretation to skills needed in a variety of post-graduate and/or occupational scenarios. Offered fall semester of even years.","offering":"Offered fall semester of even years.","sourcePage":201},"THEA 216":{"code":"THEA 216","title":"History of Theatre","credits":"3","description":"This course gives an overview of theatre history and aesthetic styles, explores the methods of theatre artists, and provides a literary perspective from ancient ceremonies to modern day. Offered fall semester odd years. Same as ENGL 216 Literary Genres: Drama","offering":"Offered fall semester odd years.","sourcePage":201},"THEA 304":{"code":"THEA 304","title":"Directing and Advanced Production","credits":"3","description":"This is a workshop course that will explore the directing and production of an entire one act play by coordinating and executing all aspects of the production. Prerequisites: THEA 104, THEA 106, and THEA 306","offering":"","sourcePage":201},"THEA 306":{"code":"THEA 306","title":"Acting II","credits":"3","description":"Students will explore advanced acting techniques building on concepts covered in Acting I. Techniques include Stanislavski’s Method, Strasberg’s Method, and other performing approaches to reinforce acting as a disciplined art. Offered fall semester of even years. Prerequisite: THEA 106","offering":"Offered fall semester of even years.","sourcePage":201},"THEA 307":{"code":"THEA 307","title":"Shakespeare","credits":"3","description":"This course will be an in-depth examination of Shakespeare’s plays and poetry. Opportunities include attending/participating in at least one Shakespeare performance/event. Offered spring semester even years. Same as ENGL 307 Prerequisite: ENGL 220 or consent of instructor","offering":"Offered spring semester even years.","sourcePage":201}}};
